using QuickBalance.API.CLS;
using System.Data;

namespace QuickBalance.API.DB
{
    public class DayBookDB
    {
        private readonly DBConn db;
        public Variable Variables = new Variable();
        public Function Functions = new Function();
        string qry = "";

        // Table Names
        string tb_name = "";
        public string tableRecPay = "";
        public string tableName = "DB" + DateTime.Now.Hour.ToString() + "_" + DateTime.Now.Minute.ToString() + "_" + DateTime.Now.Second.ToString();
        public string OpTable = "OP" + DateTime.Now.Hour.ToString() + "_" + DateTime.Now.Minute.ToString() + "_" + DateTime.Now.Second.ToString();
        public string tbPURD = "TMP_PURD" + DateTime.Now.Hour.ToString() + "_" + DateTime.Now.Minute.ToString() + "_" + DateTime.Now.Second.ToString();
        public string tbSALD = "TMP_SALD" + DateTime.Now.Hour.ToString() + "_" + DateTime.Now.Minute.ToString() + "_" + DateTime.Now.Second.ToString();
        public string TB_REFDTLS = "TB_REFDTLS_" + DateTime.Now.Hour.ToString() + "_" + DateTime.Now.Minute.ToString() + "_" + DateTime.Now.Second.ToString();

        public DayBookDB(DBConn dbConn)
        {
            db = dbConn;
        }

        public async Task<decimal> SelectedCashOpening(string RepDate, int AdjCd, bool CTable, bool DTable, bool Unapproved)
        {
            decimal bal = 0;
            if (CTable)
                await CreateTable(Variables.fyStartDate.ToString(Variables.format), RepDate, "DB", Unapproved: Unapproved);

            if (AdjCd == Variables.CashCD)
            {
                qry = "SELECT (SUM(IIF(RECCASH IS NULL,0,RECCASH))-SUM(IIF(PAYCASH IS NULL,0,PAYCASH))) AS BALANCE FROM " + tableName + " WHERE ADJCD='" + AdjCd + "'";
                bal = await db.ReturnDecValue(qry);
            }
            else
            {
                qry = "SELECT (SUM(IIF(PAYCASH IS NULL,0,PAYCASH))+SUM(IIF(PAYAMT IS NULL,0,PAYAMT))-SUM(IIF(RECCASH IS NULL,0,RECCASH))-SUM(IIF(RECAMT IS NULL,0,RECAMT))) AS BALANCE FROM " + tableName + " WHERE ACCID='" + AdjCd + "'";
                bal = await db.ReturnDecValue(qry);
            }

            if (DTable)
                await DropTable();

            return bal;
        }

        public async Task<int> CreateTable(string FromDate, string ToDate, string type, bool SkipTbCr = false, bool IsDetail = false, bool FromLedger = false, bool MultiCurr = false, int MultiCurrCode = 0, bool MultiCurrMode = false, bool CostCenter = false, bool VatSummary = false, bool StkIssRecAdj = false, bool IFRS = false, bool Unapproved = true)
