        /* FROM PURCHASE*/@"  SELECT *,4 AS LORD FROM (SELECT PURD.SLCODE, PURD.PURDATE AS VRDATE ,'0'  AS RECID,'0' AS RECPARTICULARS,'0' AS RECTYPE,0 AS RECCASH,0 AS RECAMT,PURD.ORDNO AS PAYID, ACCMAS.ACCNAME AS PAYPARTICULARS,N'" + LngTB.Purchase + "' AS PAYTYPE,IIF(PURD.BTYPE='C' AND PURD.ADJCD='" + Variables.CashCD + "' ," + (MultiCurr && MultiCurrMode ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT*PURD.CURCONRATE,PURD.AMOUNT)" : MultiCurr ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT/PURD.CURCONRATE,PURD.AMOUNT)" : "PURD.AMOUNT") + ",'0') AS PAYCASH,IIF(PURD.BTYPE<>'C' OR PURD.ADJCD<>'" + Variables.CashCD + @"'  ," + (MultiCurr && MultiCurrMode ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT*PURD.CURCONRATE,PURD.AMOUNT)" : MultiCurr ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT/PURD.CURCONRATE,PURD.AMOUNT)" : "PURD.AMOUNT") + ",'0') AS PAYAMT,ACCMAS.ID AS ACCID,PURD.ADJCD ,PURM.REMARKS AS NARRATION,IIF(PURM.BILLNO IS NOT NULL AND PURM.BILLNO <>'',PURM." + Functions.VSDOCNO() + @"+'" + (FromLedger ? "#@#" : "-") + "'+PURM.BILLNO,PURM." + Functions.VSDOCNO() + @") AS INVTEXT,IIF(PURD.BTYPE<>'R',PURD.ADJCD,PURD.SUPCODE) AS ADACC,PURM.REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
