                                            FROM (((" + TB_PURD + " INNER JOIN ACCMAS ON PURD.SUPCODE = ACCMAS.ID) INNER JOIN " + Functions.BRTBSTMNT_WITH_BRNAME("PURM") + @"PURM ON PURD.VRTYPE=PURM.VRTYPE AND PURD.VRNO=PURM.VRNO ) INNER JOIN ACCMAS ACCMAS_1 ON CASE WHEN PURD.BTYPE='R' THEN PURD.SUPCODE  WHEN PURD.BTYPE='CD' OR PURD.BTYPE='B' OR PURD.ADJCD<>" + Variables.CashCD + @" THEN PURD.ADJCD  END = ACCMAS_1.ID) INNER JOIN TAXMAS ON PURD.CODE=TAXMAS.CODE 
