          @" UNION ALL(SELECT PURD.SLCODE, PURD.PURDATE AS VRDATE ,'0' AS RECID,'' AS RECPARTICULARS,'' AS RECTYPE,'0'  AS RECCASH,0 AS RECAMT,IIF(PURD.BTYPE='C' AND PURD.ADJCD='" + Variables.CashCD + "','0',PURD.ORDNO)  AS PAYID, IIF(PURD.BTYPE='C' AND PURD.ADJCD='" + Variables.CashCD + "','0',ACCMAS_1.ACCNAME) AS PAYPARTICULARS,IIF(PURD.BTYPE='C' AND PURD.ADJCD='" + Variables.CashCD + "','0',N'" + LngTB.Purchase + "')  AS PAYTYPE,0 AS PAYCASH,CASE WHEN PURD.BTYPE='C' AND PURD.ADJCD='" + Variables.CashCD + "' THEN 0 WHEN (PURD.BTYPE<>'C' OR PURD.ADJCD<>'" + Variables.CashCD + "') THEN -1*(" + (MultiCurr && MultiCurrMode ? "IIF(PURD.CURCONRATE<>0,PURD.TAXAMT*PURD.CURCONRATE,PURD.TAXAMT)" : MultiCurr ? "IIF(PURD.CURCONRATE<>0,PURD.TAXAMT/PURD.CURCONRATE,PURD.TAXAMT)" : "PURD.TAXAMT") + ") END  AS PAYAMT,IIF(PURD.BTYPE='R',PURD.SUPCODE,PURD.ADJCD) AS ACCID,IIF(PURD.BTYPE='C' AND PURD.ADJCD<>'" + Variables.CashCD + "',PURD.CODE,PURD.ADJCD ) AS ADJCD ," + (IsDetail ? "ACCMAS_2.ACCNAME" : "N'" + LngTB.Purchase + "'") + " AS NARRATION ,IIF(PURM.BILLNO IS NOT NULL AND PURM.BILLNO <>'',PURM." + Functions.VSDOCNO() + @"+'" + (FromLedger ? "#@#" : "-") + "'+PURM.BILLNO,PURM." + Functions.VSDOCNO() + @") AS INVTEXT,CASE WHEN PURD.BTYPE='B' THEN PURD.SUPCODE WHEN PURD.BTYPE='C' AND PURD.ADJCD<>'" + Variables.CashCD + @"' THEN PURD.CODE WHEN PURD.BTYPE<>'B' THEN PURD.ADJCD END AS ADACC,PURM.REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
