/*GCC Purchase Posting*/ @" UNION ALL(SELECT PURD.SLCODE, PURD.PURDATE AS VRDATE ,IIF(ACCMAS_1.MGROUP=4,'0',PURD.ORDNO) AS RECID,IIF(ACCMAS_1.MGROUP=4,'0',ACCMAS_1.ACCNAME) AS RECPARTICULARS,IIF(ACCMAS_1.MGROUP=4,'0',N'" + LngTB.Purchase + "') AS RECTYPE,'0'  AS RECCASH,CASE WHEN ACCMAS_1.MGROUP='4' THEN 0 WHEN ACCMAS_1.MGROUP<>'4' AND (PURD.CODE<>'" + Variables.DiscCD + "' OR PURD.DFLAG='" + false + "') THEN " + (MultiCurr && MultiCurrMode ? "IIF(PURD.CURCONRATE<>0,PURD.TAXAMT*PURD.CURCONRATE,PURD.TAXAMT)" : MultiCurr ? "IIF(PURD.CURCONRATE<>0,PURD.TAXAMT/PURD.CURCONRATE,PURD.TAXAMT)" : "PURD.TAXAMT") + " WHEN ACCMAS_1.MGROUP<>'4' AND PURD.CODE='" + Variables.DiscCD + "' AND PURD.VATFLG='" + false + "' AND PURD.DFLAG='" + true + "' THEN -1*(" + (MultiCurr && MultiCurrMode ? "IIF(PURD.CURCONRATE<>0,PURD.TAXAMT*PURD.CURCONRATE,PURD.TAXAMT)" : MultiCurr ? "IIF(PURD.CURCONRATE<>0,PURD.TAXAMT/PURD.CURCONRATE,PURD.TAXAMT)" : "PURD.TAXAMT") + ") END AS RECAMT,IIF(ACCMAS_1.MGROUP=4,'0',PURD.ORDNO)  AS PAYID, '0' AS PAYPARTICULARS,'0'  AS PAYTYPE,0 AS PAYCASH,'0'   AS PAYAMT,PURD.GCCCD AS ACCID,PURD.ADJCD ,N'" + LngTB.Purchase + "' AS NARRATION ,IIF(PURM.BILLNO IS NOT NULL AND PURM.BILLNO <>'',PURM." + Functions.VSDOCNO() + @"+'" + (FromLedger ? "#@#" : "-") + "'+PURM.BILLNO,PURM." + Functions.VSDOCNO() + @") AS INVTEXT,IIF(PURD.BTYPE='B',PURD.SUPCODE,PURD.ADJCD) AS ADACC,PURM.REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
