                        WHERE PURM.STATUS='Updated' AND PURM.VRTYPE='T' AND IIF(PURM.TRTYPE IS NULL,'',PURM.TRTYPE)='R' AND PURM.PURDATE BETWEEN '" + FromDate + "' AND '" + ToDate + "'" + (MultiCurr ? " AND PURM.CURCODE=" + MultiCurrCode + " " : "") + Functions.APRVLR(true, Unapproved, "PURM") + Functions.BRSTMNT("PURM", true) + " )" +

