/*FROM PUR.RETURN*/ @" UNION ALL SELECT *,3 AS LORD FROM ( SELECT PURD.SLCODE, PURD.PURDATE AS VRDATE ,PURD.ORDNO  AS RECID,ACCMAS.ACCNAME AS RECPARTICULARS,N'" + LngTB.Pur__Return + "' AS RECTYPE,IIF(PURD.BTYPE='C' AND PURD.ADJCD='" + Variables.CashCD + "' ," + (MultiCurr && MultiCurrMode ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT*PURD.CURCONRATE,PURD.AMOUNT)" : MultiCurr ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT/PURD.CURCONRATE,PURD.AMOUNT)" : "PURD.AMOUNT") + ",'0') AS RECCASH,IIF(PURD.BTYPE<>'C' OR PURD.ADJCD<>" + Variables.CashCD + @" ," + (MultiCurr && MultiCurrMode ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT*PURD.CURCONRATE,PURD.AMOUNT)" : MultiCurr ? "IIF(PURD.CURCONRATE<>0,PURD.AMOUNT/PURD.CURCONRATE,PURD.AMOUNT)" : "PURD.AMOUNT") + ",'0') AS RECAMT,'0' AS PAYID, '0' AS PAYPARTICULARS,'0' AS PAYTYPE,0 AS PAYCASH,0 AS PAYAMT,ACCMAS.ID AS ACCID,PURD.ADJCD  ,PURM.REMARKS AS NARRATION,IIF(PURM.MNBILLNO IS NOT NULL AND PURM.MNBILLNO <>'',PURM." + Functions.VSDOCNO() + @"+'" + (FromLedger ? "#@#" : "-") + "'+PURM.MNBILLNO,PURM." + Functions.VSDOCNO() + @") AS INVTEXT,IIF(PURD.BTYPE='C',PURD.ADJCD,PURD.SUPCODE) AS ADACC,PURM.REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
