FROM (ACCMAS INNER JOIN (SELECT VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE, 7 AS SALLCD, SUM(NETAMOUNT - TAXAMOUNT) AS AMOUNT" + Functions.BRTBSTMNT_GET_BRNAME() + @" FROM " + Functions.BRTBSTMNT_WITH_BRNAME("PARTYDBCR") + @"PARTYDBCR INNER JOIN (SELECT CODE, VATCODE, SALCODE FROM TAXMAS) TAXMAS ON PARTYDBCR.TAXCODE = TAXMAS.CODE WHERE VRTYPE = 'CDN' AND CANCELFLG = 'FALSE' AND VRDATE BETWEEN '" + FromDate + "' AND '" + ToDate + "'" + Functions.APRVLR(true, Unapproved, "PARTYDBCR") + Functions.BRSTMNT("PARTYDBCR", true) + " GROUP BY VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE" + Functions.BRTBSTMNT_GET_BRNAME() + @" ) PARTYDBCR ON ACCMAS.ID = PARTYDBCR.SALLCD)
" + (MultiCurr ? " WHERE PARTYDBCR.CURCODE = " + MultiCurrCode + " " : "") + @"
UNION ALL
SELECT 0 AS SLCODE, PARTYDBCR.VRDATE AS VRDATE, PARTYDBCR.VRNO AS RECID, ACCMAS.ACCNAME AS RECPARTICULARS,N'" + LngTB.Customer_Debit_Note + "' AS RECTYPE, IIF(PARTYDBCR.BTYPE = 'C' AND PARTYDBCR.CASHLCD = " + Variables.CashCD + "," + (MultiCurr && MultiCurrMode ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT*PARTYDBCR.CURCONRATE, PARTYDBCR.AMOUNT)" : MultiCurr ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT/PARTYDBCR.CURCONRATE, PARTYDBCR.AMOUNT)" : "PARTYDBCR.AMOUNT") + ", 0) AS RECCASH, IIF(PARTYDBCR.BTYPE = 'C' AND PARTYDBCR.CASHLCD = " + Variables.CashCD + @", 0," + (MultiCurr && MultiCurrMode ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT*PARTYDBCR.CURCONRATE, SALD.AMOUNT)" : MultiCurr ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT/PARTYDBCR.CURCONRATE, PARTYDBCR.AMOUNT)" : "PARTYDBCR.AMOUNT") + ") AS RECAMT, 0 AS PAYID, '0' AS PAYPARTICULARS, '0' AS PAYTYPE, 0 AS PAYCASH, 0 AS PAYAMT, ACCMAS.ID AS ACCID, IIF(PARTYDBCR.BTYPE = 'C', PARTYDBCR.CASHLCD, PARTYDBCR.BANKLCD) AS ADJCD," + (!FromLedger || IsDetail ? "PARTYDBCR.NARRATION" : "IIF(PARTYDBCR.BTYPE = 'C' AND PARTYDBCR.CASHLCD = " + Variables.CashCD + ", '_SUMMARY_', PARTYDBCR.NARRATION)") + " AS NARRATION, PARTYDBCR." + Functions.VSDOCNO() + @" AS INVTEXT, IIF(PARTYDBCR.BTYPE = 'C', PARTYDBCR.CASHLCD, IIF(PARTYDBCR.BTYPE = 'B', PARTYDBCR.BANKLCD, PARTYDBCR.PARTYCD)) AS ADACC, PARTYDBCR.NARRATION AS REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
FROM (ACCMAS INNER JOIN (SELECT VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE, 7 AS SALLCD, SUM(TAXAMOUNT) AS AMOUNT" + Functions.BRTBSTMNT_GET_BRNAME() + @" FROM " + Functions.BRTBSTMNT_WITH_BRNAME("PARTYDBCR") + @"PARTYDBCR INNER JOIN (SELECT CODE, VATCODE, SALCODE FROM TAXMAS) TAXMAS ON PARTYDBCR.TAXCODE = TAXMAS.CODE WHERE VRTYPE = 'CDN' AND CANCELFLG = 'FALSE' AND VRDATE BETWEEN '" + FromDate + "' AND '" + ToDate + "'" + Functions.APRVLR(true, Unapproved, "PARTYDBCR") + Functions.BRSTMNT("PARTYDBCR", true) + " GROUP BY VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE" + Functions.BRTBSTMNT_GET_BRNAME() + @" ) PARTYDBCR ON ACCMAS.ID = " + (VatSummary ? "PARTYDBCR.SALLCD" : "PARTYDBCR.VATCODE") + @")
WHERE AMOUNT <> 0" + (MultiCurr ? " AND PARTYDBCR.CURCODE = " + MultiCurrCode + " " : "") + @"
UNION ALL
SELECT 0 AS SLCODE, PARTYDBCR.VRDATE AS VRDATE, 0 AS RECID, '0' AS RECPARTICULARS, '0' AS RECTYPE, 0 AS RECCASH, 0 AS RECAMT, PARTYDBCR.VRNO AS PAYID, ACCMAS.ACCNAME AS PAYPARTICULARS, N'" + LngTB.Customer_Debit_Note + "' AS PAYTYPE, 0 AS PAYCASH, " + (MultiCurr && MultiCurrMode ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT*PARTYDBCR.CURCONRATE, SALD.AMOUNT)" : MultiCurr ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT/PARTYDBCR.CURCONRATE, PARTYDBCR.AMOUNT)" : "PARTYDBCR.AMOUNT") + " AS PAYAMT, ACCMAS.ID AS ACCID, IIF(PARTYDBCR.BTYPE = 'C', PARTYDBCR.SALCODE, PARTYDBCR.BANKLCD) AS ADJCD,  N'" + (IsDetail ? Variables.VatLbl : LngTB.Sales) + "' AS NARRATION, PARTYDBCR." + Functions.VSDOCNO() + @" AS INVTEXT, IIF(PARTYDBCR.BTYPE = 'C', PARTYDBCR.SALCODE, IIF(PARTYDBCR.BTYPE = 'B', PARTYDBCR.PARTYCD, 0)) AS ADACC, PARTYDBCR.NARRATION AS REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @" 
FROM (ACCMAS INNER JOIN (SELECT VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE, 7 AS SALLCD, SUM(NETAMOUNT - TAXAMOUNT) AS AMOUNT" + Functions.BRTBSTMNT_GET_BRNAME() + @" FROM " + Functions.BRTBSTMNT_WITH_BRNAME("PARTYDBCR") + @"PARTYDBCR INNER JOIN (SELECT CODE, VATCODE, SALCODE FROM TAXMAS) TAXMAS ON PARTYDBCR.TAXCODE = TAXMAS.CODE WHERE VRTYPE = 'CDN' AND CANCELFLG = 'FALSE' AND VRDATE BETWEEN '" + FromDate + "' AND '" + ToDate + "'" + Functions.APRVLR(true, Unapproved, "PARTYDBCR") + Functions.BRSTMNT("PARTYDBCR", true) + " GROUP BY VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE" + Functions.BRTBSTMNT_GET_BRNAME() + @" ) PARTYDBCR ON ACCMAS.ID = IIF(PARTYDBCR.BTYPE = 'R', PARTYDBCR.PARTYCD, IIF(PARTYDBCR.BTYPE = 'B', PARTYDBCR.BANKLCD, PARTYDBCR.CASHLCD)))
WHERE (PARTYDBCR.BTYPE <> 'C' OR PARTYDBCR.CASHLCD <> " + Variables.CashCD + ")" + (MultiCurr ? " AND PARTYDBCR.CURCODE = " + MultiCurrCode + " " : "") + @"
UNION ALL SELECT 0 AS SLCODE, PARTYDBCR.VRDATE AS VRDATE, 0 AS RECID, '0' AS RECPARTICULARS, '0' AS RECTYPE, 0 AS RECCASH, 0 AS RECAMT, PARTYDBCR.VRNO AS PAYID, ACCMAS.ACCNAME AS PAYPARTICULARS, N'" + LngTB.Customer_Debit_Note + "' AS PAYTYPE, 0 AS PAYCASH, " + (MultiCurr && MultiCurrMode ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT*PARTYDBCR.CURCONRATE, SALD.AMOUNT)" : MultiCurr ? "IIF(PARTYDBCR.CURCONRATE <> 0, PARTYDBCR.AMOUNT/PARTYDBCR.CURCONRATE, PARTYDBCR.AMOUNT)" : "PARTYDBCR.AMOUNT") + " AS PAYAMT, ACCMAS.ID AS ACCID, IIF(PARTYDBCR.BTYPE = 'C', PARTYDBCR.VATCODE, PARTYDBCR.BANKLCD) AS ADJCD, N'" + LngTB.Sales + "' AS NARRATION, PARTYDBCR." + Functions.VSDOCNO() + @" AS INVTEXT, IIF(PARTYDBCR.BTYPE = 'C', PARTYDBCR.VATCODE, IIF(PARTYDBCR.BTYPE = 'B', PARTYDBCR.PARTYCD, 0)) AS ADACC, PARTYDBCR.NARRATION AS REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @" 
FROM (ACCMAS INNER JOIN (SELECT VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE, 7 AS SALLCD, SUM(TAXAMOUNT) AS AMOUNT" + Functions.BRTBSTMNT_GET_BRNAME() + @" FROM " + Functions.BRTBSTMNT_WITH_BRNAME("PARTYDBCR") + @"PARTYDBCR INNER JOIN (SELECT CODE, VATCODE, SALCODE FROM TAXMAS) TAXMAS ON PARTYDBCR.TAXCODE = TAXMAS.CODE WHERE VRTYPE = 'CDN' AND CANCELFLG = 'FALSE' AND VRDATE BETWEEN '" + FromDate + "' AND '" + ToDate + "'" + Functions.APRVLR(true, Unapproved, "PARTYDBCR") + Functions.BRSTMNT("PARTYDBCR", true) + " GROUP BY VRNO, VRDATE, INVNOTEXT, VSDOCNO, PARTYCD, CURCONRATE, CURCODE, BTYPE, CASHLCD, BANKLCD, NARRATION, TAXCODE, VATCODE, SALCODE" + Functions.BRTBSTMNT_GET_BRNAME() + @" ) PARTYDBCR ON ACCMAS.ID = IIF(PARTYDBCR.BTYPE = 'R', PARTYDBCR.PARTYCD, IIF(PARTYDBCR.BTYPE = 'B', PARTYDBCR.BANKLCD, PARTYDBCR.CASHLCD)))
WHERE AMOUNT <> 0 AND (PARTYDBCR.BTYPE <> 'C' OR PARTYDBCR.CASHLCD <> " + Variables.CashCD + ")" + (MultiCurr ? " AND PARTYDBCR.CURCODE = " + MultiCurrCode + " " : "") + " ) T GROUP BY SLCODE, VRDATE, RECID, RECPARTICULARS, RECTYPE, PAYID, PAYPARTICULARS, PAYTYPE, ACCID, ADJCD, NARRATION, INVTEXT, ADACC, REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
) tb ") +

                   /*Debit/Credit Note*/
                   @" UNION ALL SELECT *,IIF(RECID<>0,2,6) AS LORD FROM (SELECT DBCRNOTE.SLCODE,DBCRNOTE.VRDATE , CASE WHEN DBCRNOTE.CDTYPE='C' THEN CAST(DBCRNOTE.VRNO AS VARCHAR(150)) WHEN DBCRNOTE.CDTYPE='D' THEN '0' END AS RECID, CASE WHEN DBCRNOTE.CDTYPE='C' THEN ACCMAS.ACCNAME WHEN DBCRNOTE.CDTYPE='D' THEN '0' END AS RECPARTICULARS ,CASE WHEN DBCRNOTE.VRTYPE='CN' AND DBCRNOTE.CDTYPE='C' THEN N'" + LngTB.CrNote + "' WHEN DBCRNOTE.VRTYPE='DN' AND DBCRNOTE.CDTYPE='C' THEN N'" + LngTB.DrNote + "' WHEN DBCRNOTE.CDTYPE='D' THEN '0' END AS RECTYPE,CASE WHEN DBCRNOTE.CASHFLG='T'  AND DBCRNOTE.CDTYPE='C' AND DBCRNOTE.ADJCD='" + Variables.CashCD + "' THEN " + (MultiCurr && MultiCurrMode ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.RECEIPT*DBCRNOTE.CURCONRATE,DBCRNOTE.RECEIPT)" : MultiCurr ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.RECEIPT/DBCRNOTE.CURCONRATE,DBCRNOTE.RECEIPT)" : "DBCRNOTE.RECEIPT") + " WHEN DBCRNOTE.CASHFLG='F' OR  DBCRNOTE.ADJCD<>'" + Variables.CashCD + "' THEN 0 WHEN DBCRNOTE.CDTYPE='D' THEN 0 END AS RECCASH,CASE WHEN DBCRNOTE.CDTYPE='C' AND  (DBCRNOTE.CASHFLG='F' OR DBCRNOTE.ADJCD<>" + Variables.CashCD + @")  THEN " + (MultiCurr && MultiCurrMode ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.RECEIPT*DBCRNOTE.CURCONRATE,DBCRNOTE.RECEIPT)" : MultiCurr ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.RECEIPT/DBCRNOTE.CURCONRATE,DBCRNOTE.RECEIPT)" : "DBCRNOTE.RECEIPT") + @" WHEN DBCRNOTE.CDTYPE='D' THEN 0 WHEN DBCRNOTE.CASHFLG='T' THEN 0 END AS RECAMT , 
                                            CASE WHEN DBCRNOTE.CDTYPE='D' THEN CAST(DBCRNOTE.VRNO AS VARCHAR(150)) WHEN DBCRNOTE.CDTYPE='C' THEN '0' END AS PAYID, CASE WHEN DBCRNOTE.CDTYPE='D' THEN ACCMAS.ACCNAME WHEN DBCRNOTE.CDTYPE='C' THEN '0' END AS PAYPARTICULARS ,CASE WHEN DBCRNOTE.VRTYPE='DN' AND DBCRNOTE.CDTYPE='D' THEN N'" + LngTB.DrNote + "' WHEN DBCRNOTE.VRTYPE='CN' AND DBCRNOTE.CDTYPE='D' THEN N'" + LngTB.CrNote + "' WHEN DBCRNOTE.CDTYPE='C' THEN '0' END AS PAYTYPE,CASE WHEN DBCRNOTE.CASHFLG='T' AND DBCRNOTE.ADJCD='" + Variables.CashCD + "' AND DBCRNOTE.CDTYPE='D' THEN " + (MultiCurr && MultiCurrMode ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.PAYMENT*DBCRNOTE.CURCONRATE,DBCRNOTE.PAYMENT)" : MultiCurr ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.PAYMENT/DBCRNOTE.CURCONRATE,DBCRNOTE.PAYMENT)" : "DBCRNOTE.PAYMENT") + " WHEN DBCRNOTE.CDTYPE='C' THEN 0 WHEN DBCRNOTE.CASHFLG='F' OR DBCRNOTE.ADJCD<>'" + Variables.CashCD + "' THEN 0 END  AS PAYCASH,CASE WHEN DBCRNOTE.CDTYPE='D' AND  (DBCRNOTE.CASHFLG='F' OR DBCRNOTE.ADJCD<>'" + Variables.CashCD + "')  THEN " + (MultiCurr && MultiCurrMode ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.PAYMENT*DBCRNOTE.CURCONRATE,DBCRNOTE.PAYMENT)" : MultiCurr ? "IIF(DBCRNOTE.CURCONRATE<>0,DBCRNOTE.PAYMENT/DBCRNOTE.CURCONRATE,DBCRNOTE.PAYMENT)" : "DBCRNOTE.PAYMENT") + " WHEN DBCRNOTE.CDTYPE='C' THEN 0 WHEN DBCRNOTE.CASHFLG='T' AND DBCRNOTE.ADJCD=" + Variables.CashCD + @"  THEN 0 END AS PAYAMT ,ACCMAS.ID AS ACCID,DBCRNOTE.ADJCD ,DBCRNOTE.NARRATION,DBCRNOTE." + Functions.VSDOCNO() + @" AS INVTEXT,DBCRNOTE.ADJCD AS ADACC,DBCRNOTE.NARRATION AS REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
                                            FROM (" + Functions.BRTBSTMNT_WITH_BRNAME("DBCRNOTE") + @"DBCRNOTE INNER JOIN ACCMAS ON DBCRNOTE.CODE = ACCMAS.ID) 
                                            WHERE DBCRNOTE.VRDATE BETWEEN '" + FromDate + "' AND '" + ToDate + "' AND ACCMAS.ID<>'" + Variables.CashCD + "'" + (MultiCurr ? " AND DBCRNOTE.CURCODE=" + MultiCurrCode + " " : "") + Functions.APRVLR(true, Unapproved, "DBCRNOTE") + Functions.BRSTMNT("DBCRNOTE", true) + ") AS TBC" +
                   /*Receipt/Voucher*/
                   @" UNION ALL SELECT *,IIF(RECID<>0,1,5) AS LORD FROM(SELECT YVR.SLCODE,YVR.VRDATE , CASE WHEN YVR.CDTYPE='C' THEN CAST(YVR.VRNO AS VARCHAR(150)) WHEN YVR.CDTYPE='D' THEN '0' END AS RECID, CASE WHEN YVR.CDTYPE='C' THEN ACCMAS.ACCNAME WHEN YVR.CDTYPE='D' THEN '0' END AS RECPARTICULARS ,CASE WHEN YVR.VRTYPE='JV' AND YVR.CDTYPE='C' THEN N'" + LngTB.Journal + "' WHEN YVR.VRTYPE='PV' AND YVR.CDTYPE='C' THEN N'" + LngTB.Payment + "' WHEN YVR.VRTYPE='RV' AND YVR.CDTYPE='C' THEN N'" + LngTB.Receipt + "' WHEN  YVR.VRTYPE='GR' AND YVR.CDTYPE='C' THEN N'" + LngTB.Gen__Receipt + "' WHEN YVR.VRTYPE='GP' AND YVR.CDTYPE='C' THEN N'" + LngTB.Gen__Payment + "' WHEN YVR.CDTYPE='D' THEN '0' END AS RECTYPE,CASE WHEN YVR.CASHFLG='T' AND YVR.ADJCD='" + Variables.CashCD + "' AND YVR.CDTYPE='C' THEN " + (MultiCurr && MultiCurrMode ? "IIF(YVR.CURCONRATE<>0,YVR.RECEIPT*YVR.CURCONRATE,YVR.RECEIPT)" : MultiCurr ? "IIF(YVR.CURCONRATE<>0,YVR.RECEIPT/YVR.CURCONRATE,YVR.RECEIPT)" : "YVR.RECEIPT") + " WHEN YVR.CASHFLG='F' OR YVR.ADJCD<>'" + Variables.CashCD + "' THEN 0 WHEN YVR.CDTYPE='D' THEN 0 END AS RECCASH,CASE WHEN YVR.CDTYPE='C' AND ( YVR.CASHFLG='F' OR YVR.ADJCD<>'" + Variables.CashCD + "') THEN " + (MultiCurr && MultiCurrMode ? "IIF(YVR.CURCONRATE<>0,YVR.RECEIPT*YVR.CURCONRATE,YVR.RECEIPT)" : MultiCurr ? "IIF(YVR.CURCONRATE<>0,YVR.RECEIPT/YVR.CURCONRATE,YVR.RECEIPT)" : "YVR.RECEIPT") + " WHEN YVR.CDTYPE='D' THEN 0 WHEN YVR.CASHFLG='T' AND YVR.ADJCD='" + Variables.CashCD + @"' THEN 0 END AS RECAMT , 
                                            CASE WHEN YVR.CDTYPE='D' THEN CAST(YVR.VRNO AS VARCHAR(150)) WHEN YVR.CDTYPE='C' THEN '0' END AS PAYID, CASE WHEN YVR.CDTYPE='D' THEN ACCMAS.ACCNAME WHEN YVR.CDTYPE='C' THEN '0' END AS PAYPARTICULARS ,CASE WHEN YVR.VRTYPE='JV' AND YVR.CDTYPE='D' THEN N'" + LngTB.Journal + "' WHEN YVR.VRTYPE='RV' AND YVR.CDTYPE='D' THEN N'" + LngTB.Receipt + "' WHEN YVR.VRTYPE='PV' AND YVR.CDTYPE='D' THEN N'" + LngTB.Payment + "' WHEN YVR.VRTYPE='GP' AND YVR.CDTYPE='D' THEN N'" + LngTB.Gen__Payment + "' WHEN YVR.VRTYPE='GR' AND YVR.CDTYPE='D' THEN N'" + LngTB.Gen__Receipt + "' WHEN YVR.CDTYPE='C' THEN '0' END AS PAYTYPE,CASE WHEN YVR.CASHFLG='T' AND YVR.ADJCD='" + Variables.CashCD + "' AND YVR.CDTYPE='D' THEN " + (MultiCurr && MultiCurrMode ? "IIF(YVR.CURCONRATE<>0,YVR.PAYMENT*YVR.CURCONRATE,YVR.PAYMENT)" : MultiCurr ? "IIF(YVR.CURCONRATE<>0,YVR.PAYMENT/YVR.CURCONRATE,YVR.PAYMENT)" : "YVR.PAYMENT") + " WHEN YVR.CDTYPE='C' THEN 0 WHEN  YVR.CASHFLG='F' OR YVR.ADJCD<>'" + Variables.CashCD + "' THEN 0 END  AS PAYCASH,CASE WHEN YVR.CDTYPE='D' AND  (YVR.CASHFLG='F' OR YVR.ADJCD<>'" + Variables.CashCD + "') THEN " + (MultiCurr && MultiCurrMode ? "IIF(YVR.CURCONRATE<>0,YVR.PAYMENT*YVR.CURCONRATE,YVR.PAYMENT)" : MultiCurr ? "IIF(YVR.CURCONRATE<>0,YVR.PAYMENT/YVR.CURCONRATE,YVR.PAYMENT)" : "YVR.PAYMENT") + " WHEN YVR.CDTYPE='C' THEN 0 WHEN YVR.CASHFLG='T' AND YVR.ADJCD='" + Variables.CashCD + @"' THEN 0 END AS PAYAMT ,ACCMAS.ID AS ACCID,YVR.ADJCD ,IIF(YVR.DESCRIPTION IS NOT NULL AND YVR.DESCRIPTION<>'',YVR.DESCRIPTION,YVR.NARRATION) AS NARRATION,IIF((YVR.VRTYPE='RV' OR YVR.VRTYPE='PV') AND YVR.CHQNO IS NOT NULL AND YVR.CHQNO <>'',YVR." + Functions.VSDOCNO() + @"+'-'+YVR.CHQNO, YVR." + Functions.VSDOCNO() + @") AS INVTEXT,YVR.ADJCD AS ADACC,IIF(YVR.DESCRIPTION IS NOT NULL AND YVR.DESCRIPTION <> '', YVR.DESCRIPTION, YVR.NARRATION) AS REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"
                                            FROM (" + Functions.BRTBSTMNT_WITH_BRNAME("YVR") + @"YVR INNER JOIN ACCMAS ON YVR.CODE = ACCMAS.ID) 
                                            WHERE YVR.VRDATE BETWEEN '" + FromDate + "' AND '" + ToDate + "' AND ACCMAS.ID<>'" + Variables.CashCD + "' AND YVR.VRTYPE<>'JV'" + (MultiCurr ? " AND YVR.CURCODE=" + MultiCurrCode + " " : "") + Functions.APRVLR(true, Unapproved, "YVR") + Functions.BRSTMNT("YVR", true) + ") AS TBV" +

