        public async Task DropTable()
        {
            await Drop(tableName);
            await Drop(OpTable);
            await Drop(tb_name);
            await Drop(tableRecPay);
        }

        public async Task<int> Drop(string table)
        {
            if (string.IsNullOrWhiteSpace(table))
                return 0;

            qry = "DROP TABLE " + table;

            return await db.Execute(qry);
        }

        public async Task<DataTable> SelectedCashBookDates(int AdjCd)
        {
            qry = "SELECT DISTINCT VRDATE AS VRDATE FROM " + tableName + " WHERE ((RECCASH <>'0' OR RECAMT<>'0') OR (PAYCASH <>'0' OR PAYAMT<>'0')) AND ADJCD='" + AdjCd + "' ORDER BY VRDATE";
            return await db.GetDatatable(qry);
        }

        public async Task<decimal> SelectedCashOpenBalByDate(DateTime RepDate, int AdjCd)
        {
            if (AdjCd == Variables.CashCD)
            {
                qry = "SELECT  (SUM(CASE WHEN RECCASH IS NOT NULL THEN  RECCASH WHEN RECCASH IS NULL THEN 0 END)+SUM(CASE WHEN RECAMT IS NOT NULL THEN RECAMT WHEN RECAMT IS NULL THEN 0 END) - SUM(CASE WHEN PAYCASH IS NOT NULL THEN PAYCASH WHEN PAYCASH IS NULL THEN 0 END)- SUM(CASE WHEN PAYAMT IS NOT NULL THEN PAYAMT WHEN PAYAMT IS NULL THEN 0 END)) AS BALANCE FROM " + tableName + " WHERE VRDATE<'" + RepDate + "' AND ADJCD='" + AdjCd + "'";
                DataTable dt = await db.GetDatatable(qry);
                if (dt.Rows.Count > 0)
                {
                    DataRow dr = dt.Rows[0];
                    if (!string.IsNullOrEmpty(dr["BALANCE"].ToString()))
                        return Convert.ToDecimal(dr["BALANCE"]);
                    else
                        return 0;
                }
                else
                    return 0;
            }
            else
            {
                qry = "SELECT  (SUM(CASE WHEN PAYCASH IS NOT NULL THEN PAYCASH WHEN PAYCASH IS NULL THEN 0 END)+ SUM(CASE WHEN PAYAMT IS NOT NULL THEN PAYAMT WHEN PAYAMT IS NULL THEN 0 END)-SUM(CASE WHEN RECCASH IS NOT NULL THEN RECCASH WHEN RECCASH IS NULL THEN 0 END)-SUM(CASE WHEN RECAMT IS NOT NULL THEN RECAMT WHEN RECAMT IS NULL THEN 0 END)) AS BALANCE FROM " + tableName + " WHERE VRDATE<'" + RepDate + "' AND ACCID='" + AdjCd + "'";
                DataTable dt = await db.GetDatatable(qry);
                if (dt.Rows.Count > 0)
                {
                    DataRow dr = dt.Rows[0];
                    if (!string.IsNullOrEmpty(dr["BALANCE"].ToString()))
                        return Convert.ToDecimal(dr["BALANCE"]);
                    else
                        return 0;
                }
                else
                    return 0;
            }
        }

        public async Task<DataTable> SelectedCashTransactionsOnDate(DateTime RepDate, int AdjCd, bool VatSummary)
        {
            if (AdjCd == Variables.CashCD)
            {
                if (VatSummary)
                    qry = "SELECT RECID,INVTEXT,FORMAT(VRDATE,'" + Variables.format + "') AS VRDATE,RECPARTICULARS,RECTYPE,IIF(SUM(RECCASH) <> 0, FORMAT(SUM(RECCASH),'" + Variables.DecString + "'), '') AS RECCASH,IIF(SUM(PAYCASH) <> 0, FORMAT(SUM(PAYCASH),'" + Variables.DecString + "'),'') AS PAYCASH, MAX(REMARKS) AS REMARKS FROM (SELECT RECID,INVTEXT,VRDATE,RECPARTICULARS,RECTYPE,RECCASH,PAYCASH, MAX(REMARKS) AS REMARKS FROM( SELECT INVTEXT,VRDATE,CASE WHEN RECCASH<>0  THEN RECID WHEN RECAMT<>0 THEN RECID WHEN PAYCASH<>0 THEN PAYID WHEN PAYAMT<>0 THEN PAYID END AS RECID,CASE WHEN RECCASH<>0 OR  RECAMT<>0 THEN RECPARTICULARS WHEN PAYCASH<>0 OR PAYAMT<>0 THEN PAYPARTICULARS END AS RECPARTICULARS ,CASE WHEN RECCASH<>0 OR RECAMT<>0 THEN RECTYPE WHEN PAYCASH<>0 OR PAYAMT<>0 THEN PAYTYPE END AS RECTYPE,CASE WHEN RECCASH<>0  THEN RECCASH WHEN RECAMT<>0 THEN RECAMT ELSE 0 END AS RECCASH,CASE WHEN PAYCASH<>0 THEN PAYCASH WHEN PAYAMT<>0 THEN PAYAMT ELSE 0 END AS PAYCASH, REMARKS FROM " + tableName + " WHERE VRDATE='" + RepDate.Date + "' AND ((RECCASH<>0) OR (PAYCASH<>0 ) OR (RECAMT<>0) OR (PAYAMT<>0 )) AND ADJCD='" + AdjCd + "') AS T GROUP BY INVTEXT,VRDATE,RECID,RECTYPE,RECCASH,PAYCASH,RECPARTICULARS) DTLS GROUP BY INVTEXT,VRDATE,RECID,RECTYPE,RECPARTICULARS ORDER BY RECID";
                else
                    qry = "SELECT RECID,INVTEXT,FORMAT(VRDATE,'" + Variables.format + "') AS VRDATE,RECPARTICULARS,RECTYPE,RECCASH,PAYCASH,MAX(REMARKS) AS REMARKS FROM( SELECT INVTEXT,VRDATE,CASE WHEN RECCASH<>0  THEN RECID WHEN RECAMT<>0 THEN RECID WHEN PAYCASH<>0 THEN PAYID WHEN PAYAMT<>0 THEN PAYID END AS RECID,CASE WHEN RECCASH<>0 OR  RECAMT<>0 THEN RECPARTICULARS WHEN PAYCASH<>0 OR PAYAMT<>0 THEN PAYPARTICULARS END AS RECPARTICULARS ,CASE WHEN RECCASH<>0 OR RECAMT<>0 THEN RECTYPE WHEN PAYCASH<>0 OR PAYAMT<>0 THEN PAYTYPE END AS RECTYPE,CASE WHEN RECCASH<>0  THEN FORMAT(RECCASH,'" + Variables.DecString + "') WHEN RECAMT<>0  THEN FORMAT(RECAMT,'" + Variables.DecString + "') END  AS RECCASH,CASE WHEN PAYCASH<>0 THEN FORMAT(PAYCASH,'" + Variables.DecString + "') WHEN PAYAMT<>0 THEN FORMAT(PAYAMT,'" + Variables.DecString + "') END AS PAYCASH,REMARKS FROM " + tableName + " WHERE VRDATE='" + RepDate.Date + "' AND ((RECCASH<>0) OR (PAYCASH<>0 ) OR (RECAMT<>0) OR (PAYAMT<>0 )) AND ADJCD='" + AdjCd + "') AS T GROUP BY INVTEXT,VRDATE,RECID,RECTYPE,RECCASH,PAYCASH,RECPARTICULARS ORDER BY RECID";
                return await db.GetDatatable(qry);
            }
            else
            {
                if (VatSummary)
                    qry = "SELECT RECID,INVTEXT,FORMAT(VRDATE,'" + Variables.format + "') AS VRDATE,RECPARTICULARS,RECTYPE,IIF(SUM(RECCASH) <> 0, FORMAT(SUM(RECCASH),'" + Variables.DecString + "'), '') AS RECCASH,IIF(SUM(PAYCASH) <> 0, FORMAT(SUM(PAYCASH),'" + Variables.DecString + "'),'') AS PAYCASH, MAX(REMARKS) AS REMARKS FROM(SELECT RECID,INVTEXT,VRDATE,RECPARTICULARS,RECTYPE,PAYCASH AS RECCASH,RECCASH AS PAYCASH, MAX(REMARKS) AS REMARKS FROM (SELECT INVTEXT,VRDATE,CASE WHEN RECCASH<>0 THEN RECID WHEN RECAMT<>0 THEN RECID WHEN PAYCASH<>0 THEN PAYID WHEN PAYAMT<>0 THEN PAYID END AS RECID,ACCMAS.ACCNAME AS RECPARTICULARS ,CASE WHEN RECCASH<>0 OR RECAMT<>0 THEN RECTYPE WHEN PAYCASH<>0 OR PAYAMT<>0 THEN PAYTYPE END AS RECTYPE,CASE WHEN RECCASH<>0 THEN RECCASH WHEN RECAMT<>0 THEN RECAMT ELSE 0 END AS RECCASH,CASE WHEN PAYCASH<>0 THEN PAYCASH WHEN PAYAMT<>0 THEN PAYAMT ELSE 0 END AS PAYCASH, REMARKS FROM " + tableName + " LEFT JOIN ACCMAS ON " + tableName + ".ADJCD=ACCMAS.ID WHERE VRDATE='" + RepDate.Date + "' AND ((RECCASH<>0) OR (PAYCASH<>0 ) OR (RECAMT<>0) OR (PAYAMT<>0 )) AND ACCID='" + AdjCd + "')T GROUP BY INVTEXT,VRDATE,RECID,RECTYPE,RECCASH,PAYCASH,RECPARTICULARS) DTLS GROUP BY INVTEXT,VRDATE,RECID,RECTYPE,RECPARTICULARS ORDER BY RECID";
                else
                    qry = "SELECT RECID,INVTEXT,FORMAT(VRDATE,'" + Variables.format + "') AS VRDATE,RECPARTICULARS,RECTYPE,PAYCASH AS RECCASH,RECCASH AS PAYCASH,MAX(REMARKS) AS REMARKS FROM (SELECT INVTEXT,VRDATE,CASE WHEN RECCASH<>0 THEN RECID WHEN RECAMT<>0 THEN RECID WHEN PAYCASH<>0 THEN PAYID WHEN PAYAMT<>0 THEN PAYID END AS RECID,ACCMAS.ACCNAME AS RECPARTICULARS ,CASE WHEN RECCASH<>0 OR RECAMT<>0 THEN RECTYPE WHEN PAYCASH<>0 OR PAYAMT<>0 THEN PAYTYPE END AS RECTYPE,CASE WHEN RECCASH<>0 THEN FORMAT(RECCASH,'" + Variables.DecString + "') WHEN RECAMT<>0 THEN FORMAT(RECAMT,'" + Variables.DecString + "' ) END  AS RECCASH,CASE WHEN PAYCASH<>0 THEN FORMAT(PAYCASH,'" + Variables.DecString + "') WHEN PAYAMT<>0 THEN FORMAT(PAYAMT,'" + Variables.DecString + "') END AS PAYCASH,REMARKS FROM " + tableName + " LEFT JOIN ACCMAS ON " + tableName + ".ADJCD=ACCMAS.ID WHERE VRDATE='" + RepDate.Date + "' AND ((RECCASH<>0) OR (PAYCASH<>0 ) OR (RECAMT<>0) OR (PAYAMT<>0 )) AND ACCID='" + AdjCd + "')T GROUP BY INVTEXT,VRDATE,RECID,RECTYPE,RECCASH,PAYCASH,RECPARTICULARS ORDER BY RECID";
