            else
            {
                qry = "SELECT  SUM(ISNULL(RECCASH,0)) AS RECCASH ,SUM(ISNULL(RECAMT,0)) AS RECAMT ,SUM(ISNULL(PAYCASH,0)) AS PAYCASH,SUM(ISNULL(PAYAMT,0)) AS PAYAMT FROM " + tableName + " WHERE VRDATE='" + RepDate.ToString(Variables.format) + "' AND ADJCD='" + AdjCd + "'";
                return await db.GetDatatable(qry);
            }
        }

        public async Task<decimal> Opening(string RepDate, bool Unapproved)
        {
            decimal bal = 0;
            if (Convert.ToDateTime(RepDate).Date > Variables.fyStartDate.Date)
                await CreateTable(Variables.fyStartDate.ToString(Variables.format), RepDate, "DB", Unapproved: Unapproved);
            else
                await CreateTable(Variables.fyStartDate.AddDays(-1).ToString(Variables.format), RepDate, "DB", Unapproved: Unapproved);

            qry = "SELECT (SUM(IIF(RECCASH IS NULL,0,RECCASH))-SUM(IIF(PAYCASH IS NULL,0,PAYCASH))) AS BALANCE FROM " + tableName;
            bal = await db.ReturnDecValue(qry);

            await DropTable();

            return bal;
        }

        public async Task<DataTable> Dates()
        {
            qry = "SELECT DISTINCT VRDATE FROM " + tableName + " WHERE RECCASH<>'0' OR RECAMT<>'0' OR PAYCASH<>'0' OR PAYAMT<>'0' ORDER BY VRDATE";
            return await db.GetDatatable(qry);
        }

        public async Task<decimal> Balance(DateTime RepDate)
        {
            qry = "SELECT (SUM(RECCASH)-SUM(PAYCASH)) AS BALANCE FROM " + tableName + " WHERE VRDATE<'" + RepDate + "'";
            return await db.ReturnDecValue(qry);
        }

