                    "UNION ALL SELECT VRDATE,IIF(RECID<>'0',RECID,NULL) AS RECID,IIF(RECPARTICULARS<>'0',RECPARTICULARS,NULL) AS RECPARTICULARS,IIF(RECTYPE<>'0',RECTYPE,NULL) AS RECTYPE,IIF(SUM(RECCASH)<>0,FORMAT(SUM(RECCASH),'" + Variables.DecString + "'),NULL) AS RECCASH,IIF(SUM(RECAMT)<>0,FORMAT(SUM(RECAMT),'" + Variables.DecString + "'),NULL) AS RECAMT FROM (" + tableName + " LEFT JOIN CUSMAS ON CUSMAS.ACCID = " + tableName + ".ACCID) LEFT JOIN SUPMAS ON SUPMAS.ACCID = " + tableName + ".ACCID WHERE VRDATE='" + RepDate.Date + "' AND (RECCASH<>'0' OR RECAMT<>'0' ) AND IIF(CUSMAS.ACCID IS NULL,IIF(SUPMAS.ACCID IS NULL,0,SUPMAS.ACCID),CUSMAS.ACCID) <> 0 AND IIF(RECTYPE IS NULL,'',RECTYPE) IN (N'" + LngTB.Purchase + "',N'" + LngTB.Pur__Return + "',N'" + LngTB.Sales + "',N'" + LngTB.Sales__Ret + "')  GROUP BY VRDATE,RECID,RECPARTICULARS,RECTYPE,RECCASH )T ORDER BY VRDATE, RECID,RECTYPE,RECAMT DESC,RECCASH DESC";
                }
            }
            return await db.GetDatatable(qry);
