                    (SELECT IIF(DTLS.RECID <> 0, DTLS.RECID, IIF(DTLS.PAYID <> 0, DTLS.PAYID, 0)) AS VRNO, DTLS.VRDATE, IIF(DTLS.RECID <> 0, DTLS.RECTYPE, IIF(DTLS.PAYID <> 0, DTLS.PAYTYPE, '')) AS VRTYPE, DTLS.INVTEXT, IIF(ACCMAS.ACCNAME IS NULL, '', ACCMAS.ACCNAME) AS ACCNAME, IIF(DTLS.PAYID <> 0, DTLS.PAYCASH+DTLS.PAYAMT, 0) AS Credit,IIF(DTLS.RECID <> 0, DTLS.RECCASH+DTLS.RECAMT, 0) AS Debit, DTLS.NARRATION, DTLS.REMARKS, DTLS.LORD" + Functions.BRTBSTMNT_GET_BRNAME() + @"
                    FROM " + tableName + " DTLS LEFT JOIN ACCMAS ON DTLS.ACCID = ACCMAS.ID WHERE (DTLS.ADJCD = " + AccId + " OR DTLS.ACCID = " + AccId + ") AND (DTLS.RECCASH <> 0 OR DTLS.PAYCASH <> 0) ) AS FINAL GROUP BY VRNO, VRDATE, VRTYPE, INVTEXT, LORD" + Functions.BRTBSTMNT_GET_BRNAME() + " ORDER BY FINAL.VRDATE, LORD, VRNO";
