MARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"   FROM " + tableName + " LEFT JOIN ACCMAS ON " + tableName + ".ACCID=ACCMAS.ID WHERE (ADJCD='" + AccId + "' OR ACCID='" + AccId + "') AND (RECCASH<>0 OR PAYCASH<>0 ) ) AS F GROUP BY VRNO,VRDATE,VRTYPE,BILLNO,ACCOUNT" + (!FromLedger || IsDetail ? ",NARRATION" : "") + ",TDATE,LORD,INVTEXT,REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @"  ORDER BY F.TDATE,F.LORD,F.VRNO";
