                    ",0 AS BALANCE, " + (!IsDetail && FromLedger ? "IIF(NARRATION='_SUMMARY_','',IIF((RECTYPE IS NOT NULL AND RECTYPE IN (N'" + LngTB.Sales + "',N'" + LngTB.Sales__Ret + "',N'" + LngTB.Purchase + "',N'" + LngTB.Pur__Return + "')) OR (PAYTYPE IS NOT NULL AND PAYTYPE IN (N'" + LngTB.Sales + "',N'" + LngTB.Sales__Ret + "',N'" + LngTB.Purchase + "',N'" + LngTB.Pur__Return + "')),REMARKS,NARRATION) ) AS NARRATION" : "IIF((RECTYPE IS NOT NULL AND RECTYPE IN (N'" + LngTB.Sales + "',N'" + LngTB.Sales__Ret + "',N'" + LngTB.Purchase + "',N'" + LngTB.Pur__Return + "')) OR (PAYTYPE IS NOT NULL AND PAYTYPE IN (N'" + LngTB.Sales + "',N'" + LngTB.Sales__Ret + "',N'" + LngTB.Purchase + "',N'" + LngTB.Pur__Return + "')),REMARKS,NARRATION) AS NARRATION") + ",FORMAT(" + tableName + ".VRDATE,'" + Variables.format + "') AS TDATE,LORD" + Functions.BRTBSTMNT_GET_BRNAME() + @"  FROM (" + tableName + " LEFT JOIN ACCMAS ON " + tableName + ".ADACC=ACCMAS.ID) LEFT JOIN ACCMAS ACCMAS_1 ON " + tableName + ".ACCID=ACCMAS_1.ID  WHERE (RECCASH<>0 OR RECAMT<>0 OR PAYCASH<>0 OR PAYAMT<>0) AND IIF(ACCMAS_1.MGROUP IS NULL,0,ACCMAS_1.MGROUP) IN (26,27,1,4) " + (GrpCode == 0 ? "" : " AND " + tableName + ".ACCID IN (SELECT ID FROM ACCMAS WHERE MGROUP='" + GrpCode + "')") + " GROUP BY  " + tableName + ".ACCID,PAYID,RECID,RECTYPE,PAYTYPE,VRDATE,RECID,INVTEXT,ACCMAS.ACCNAME, " + tableName + ".NARRATION,LORD,REMARKS" + Functions.BRTBSTMNT_GET_BRNAME() + @" " +
                    " )T ORDER BY ACCID,CONVERT(DATE,VRDATE),IIF(LORD=3,4,IIF(LORD=4,2,LORD)),VRNO" + (IsDetail ? ",NARRATION" : "");
                return await db.GetDatatable(qry);
            }
        }

