        public async Task<decimal> OpenBalance(DateTime FromDate, bool Unapproved)
        {
            qry = @"SELECT SUM(ISNULL(BALANCE,0)) AS BALANCE FROM(SELECT SUM(ISNULL(DBCRNOTE.RECEIPT,0)) - SUM(ISNULL(DBCRNOTE.PAYMENT,0)) AS BALANCE FROM(DBCRNOTE INNER JOIN ACCMAS ON DBCRNOTE.CODE = ACCMAS.ID) WHERE(ACCMAS.MGROUP = '4') AND(DBCRNOTE.VRDATE < '" + FromDate.ToString(Variables.format) + "')" + Functions.APRVLR(true, Unapproved, "DBCRNOTE") + Functions.BRSTMNT("DBCRNOTE", true) +
@" UNION ALL SELECT SUM(ISNULL(YVR.RECEIPT,0)) - SUM(ISNULL(YVR.PAYMENT,0)) AS BALANCE FROM(ACCMAS ACCMAS_1 INNER JOIN  YVR ON ACCMAS_1.ID = YVR.CODE) WHERE(ACCMAS_1.MGROUP = '4') AND(YVR.VRDATE < '" + FromDate.ToString(Variables.format) + "')" + Functions.APRVLR(true, Unapproved, "YVR") + Functions.BRSTMNT("YVR", true) +
@" UNION ALL (SELECT SUM(ISNULL(BALANCE,0)) AS BALANCE FROM(SELECT(CASE WHEN PURD.VRTYPE = 'P' THEN SUM(ISNULL(PURD.AMOUNT,0)) WHEN PURD.VRTYPE = 'R' THEN 0 END - CASE WHEN PURD.VRTYPE = 'R' THEN SUM(ISNULL(PURD.AMOUNT,0)) WHEN PURD.VRTYPE = 'P' THEN 0 END) AS BALANCE FROM((TAXMAS INNER JOIN PURD ON TAXMAS.CODE = PURD.CODE) INNER JOIN ACCMAS ON TAXMAS.PURCODE = ACCMAS.ID) WHERE PURD.BTYPE = 'C' AND PURD.ETYPE = 'T' AND PURD.PURDATE < '" + FromDate.ToString(Variables.format) + "'" + Functions.APRVLR2(true, Unapproved, "PURM", "PURD", "VRNO", "VRNO") + Functions.SUBBRSTMNT("PURM", "PURD", "VRNO", "VRNO", true) + " GROUP BY  PURD.VRTYPE" +
@" UNION ALL (SELECT(CASE WHEN PURD.VRTYPE = 'P' THEN PURD.TAXAMT WHEN PURD.VRTYPE = 'R' THEN 0 END - CASE WHEN PURD.VRTYPE = 'R' THEN PURD.TAXAMT WHEN PURD.VRTYPE = 'P' THEN 0 END) AS BALANCE FROM(PURD INNER JOIN   ACCMAS ON PURD.CODE = ACCMAS.ID) WHERE(PURD.PURDATE < '" + FromDate.ToString(Variables.format) + "') AND(PURD.BTYPE = 'C')" + Functions.APRVLR2(true, Unapproved, "PURM", "PURD", "VRNO", "VRNO") + Functions.SUBBRSTMNT("PURM", "PURD", "VRNO", "VRNO", true) + ")) T)" +
@" UNION ALL (SELECT SUM(ISNULL(BALANCE,0)) AS BALANCE FROM(SELECT(CASE WHEN SALD.VRTYPE = 'R' THEN SUM(ISNULL(SALD.AMOUNT,0)) WHEN SALD.VRTYPE = 'O' THEN 0 END - CASE WHEN SALD.VRTYPE = 'O' THEN SUM(ISNULL(SALD.AMOUNT,0))  WHEN SALD.VRTYPE = 'R' THEN 0 END) AS BALANCE FROM((TAXMAS INNER JOIN SALD ON TAXMAS.CODE = SALD.CODE) INNER JOIN ACCMAS ON TAXMAS.SALCODE = ACCMAS.ID) WHERE SALD.BTYPE = 'C' AND SALD.ETYPE = 'T' AND SALD.INVDATE < '" + FromDate.ToString(Variables.format) + "'" + Functions.APRVLR2(true, Unapproved, "SALM", "SALD", "INVNO", "VRNO") + Functions.SUBBRSTMNT("SALM", "SALD", "INVNO", "VRNO", true) + " GROUP BY SALD.VRTYPE" +
@" UNION ALL (SELECT(CASE WHEN SALD.VRTYPE = 'R' THEN SALD.TAXAMT WHEN SALD.VRTYPE = 'O' THEN 0 END - CASE WHEN SALD.VRTYPE = 'O' THEN SALD.TAXAMT WHEN SALD.VRTYPE = 'R' THEN 0 END) AS BALANCE FROM(SALD INNER JOIN   ACCMAS ON SALD.CODE = ACCMAS.ID) WHERE(SALD.INVDATE < '" + FromDate.ToString(Variables.format) + "') AND(SALD.BTYPE = 'C')" + Functions.APRVLR2(true, Unapproved, "SALM", "SALD", "INVNO", "VRNO") + Functions.SUBBRSTMNT("SALM", "SALD", "INVNO", "VRNO", true) + ") ) L)  )TB";
            return await db.ReturnDecValue(qry);
        }

