        public async Task CreateTable_ManageJournalEntry()
        {
            // Split Journal Voucher with set all adjustment code   
            bool BrNameYN = Functions.BRTBSTMNT_GET_BRNAME() == "" ? false : true;
            int R = 0;

            // Rec side
            qry = @"UPDATE " + tableName + @" SET SLCODE=-2 WHERE RECTYPE = 'Journal' AND RECID IN (SELECT RECID FROM (
SELECT COUNT(RECID) AS RECCNT, 0 AS PAYCNT, RECID FROM " + tableName + @" WHERE RECTYPE = 'Journal' AND RECID <> '0' GROUP BY RECID
UNION ALL
SELECT 0 AS RECCNT, COUNT(PAYID) AS PAYCNT, PAYID FROM " + tableName + @" WHERE PAYTYPE = 'Journal' AND PAYID <> '0' GROUP BY PAYID ) DTLS GROUP BY RECID HAVING SUM(RECCNT) = 1 AND SUM(PAYCNT) > 1)";
            R += await db.Execute(qry);

            qry = @"INSERT INTO " + tableName + @" (SLCODE, VRDATE, RECID, RECPARTICULARS, RECTYPE, RECCASH, RECAMT, PAYID, PAYPARTICULARS, PAYTYPE, PAYCASH, PAYAMT, ACCID, ADJCD, LORD, NARRATION, INVTEXT, ADACC, REMARKS" + (BrNameYN ? ", BRNAME, VSORDCD" : "") + @")
SELECT T2.SLCODE, T1.VRDATE, T1.RECID, T1.RECPARTICULARS, T1.RECTYPE, T2.PAYCASH AS RECCASH
, T2.PAYAMT AS RECAMT, T1.PAYID, T1.PAYPARTICULARS, T1.PAYTYPE, T2.RECCASH AS PAYCASH, T2.RECAMT AS PAYAMT
, T1.ACCID, T2.ACCID, T1.LORD, T1.NARRATION, T1.INVTEXT, T1.ADACC, T1.REMARKS" + (BrNameYN ? ", T1.BRNAME, T1.VSORDCD" : "") + @"
FROM " + tableName + @" T1 INNER JOIN " + tableName + @" T2 ON T1.RECTYPE = T2.PAYTYPE AND T1.RECID = T2.PAYID WHERE T1.RECTYPE = 'Journal' AND T2.PAYTYPE = 'Journal' 
AND T1.RECID IN (SELECT RECID FROM (
SELECT COUNT(RECID) AS RECCNT, 0 AS PAYCNT, RECID FROM " + tableName + @" WHERE RECTYPE = 'Journal' AND RECID <> '0' GROUP BY RECID
UNION ALL
SELECT 0 AS RECCNT, COUNT(PAYID) AS PAYCNT, PAYID FROM " + tableName + @" WHERE PAYTYPE = 'Journal' AND PAYID <> '0' GROUP BY PAYID ) DTLS GROUP BY RECID HAVING SUM(RECCNT) = 1 AND SUM(PAYCNT) > 1)";
            R += await db.Execute(qry);

            qry = @"DELETE FROM " + tableName + @" WHERE RECTYPE = 'Journal' AND SLCODE = -2";
            R += await db.Execute(qry);

            // Pay Side
            qry = @"UPDATE " + tableName + @" SET SLCODE='-2' WHERE PAYTYPE = 'Journal' AND PAYID IN (SELECT DTLS.RECID FROM (
SELECT COUNT(RECID) AS RECCNT, 0 AS PAYCNT, RECID FROM " + tableName + @" WHERE RECTYPE = 'Journal' AND RECID <> '0' GROUP BY RECID
UNION ALL
SELECT 0 AS RECCNT, COUNT(PAYID) AS PAYCNT, PAYID FROM " + tableName + @" WHERE PAYTYPE = 'Journal' AND PAYID <> '0' GROUP BY PAYID ) DTLS GROUP BY RECID HAVING SUM(RECCNT) > 1 AND SUM(PAYCNT) = 1)";
            R += await db.Execute(qry);

            qry = @"INSERT INTO " + tableName + @" (SLCODE, VRDATE, RECID, RECPARTICULARS, RECTYPE, RECCASH, RECAMT, PAYID, PAYPARTICULARS, PAYTYPE, PAYCASH, PAYAMT, ACCID, ADJCD, LORD, NARRATION, INVTEXT, ADACC, REMARKS" + (BrNameYN ? ", BRNAME, VSORDCD" : "") + @")
SELECT T2.SLCODE, T1.VRDATE, T1.RECID, T1.RECPARTICULARS, T1.RECTYPE, T2.PAYCASH AS RECCASH
, T2.PAYAMT AS RECAMT, T1.PAYID, T1.PAYPARTICULARS, T1.PAYTYPE, T2.RECCASH AS PAYCASH, T2.RECAMT AS PAYAMT
, T1.ACCID, T2.ACCID, T1.LORD, T1.NARRATION, T1.INVTEXT, T1.ADACC, T1.REMARKS" + (BrNameYN ? ", T1.BRNAME, T1.VSORDCD" : "") + @"
FROM " + tableName + @" T1 INNER JOIN " + tableName + @" T2 ON T1.PAYTYPE = T2.RECTYPE AND T1.PAYID = T2.RECID WHERE T1.PAYTYPE = 'Journal' AND T2.RECTYPE = 'Journal' 
AND T1.PAYID IN (SELECT RECID FROM (
SELECT COUNT(RECID) AS RECCNT, 0 AS PAYCNT, RECID FROM " + tableName + @" WHERE RECTYPE = 'Journal' AND RECID <> '0' GROUP BY RECID
UNION ALL
SELECT 0 AS RECCNT, COUNT(PAYID) AS PAYCNT, PAYID FROM " + tableName + @" WHERE PAYTYPE = 'Journal' AND PAYID <> '0' GROUP BY PAYID ) DTLS GROUP BY RECID HAVING SUM(RECCNT) > 1 AND SUM(PAYCNT) = 1)";
            R += await db.Execute(qry);

            qry = @"DELETE FROM " + tableName + @" WHERE PAYTYPE = 'Journal' AND SLCODE = -2";
            R += await db.Execute(qry);

            //
        }

