        public async Task<DataTable> CashLedgerGrpByAcc(int AccId, bool IsDetail = false, bool FromLedger = false)
        {
            qry = "SELECT GRPNAME,'" + AccId + "' AS ACCID,ACCOUNT,VRTYPE,Format(SUM(Credit),'" + Variables.DecString + "') AS Credit,Format(SUM(Debit),'" + Variables.DecString + "') AS Debit FROM (SELECT GRPLDG.GROUPNAME AS GRPNAME,IIF(ACCMAS.ACCNAME IS NOT NULL," + (!FromLedger || IsDetail ? "ACCMAS.ACCNAME" : "IIF(NARRATION='_SUMMARY_',IIF(RECID<>'0',(case when RECTYPE=N'" + LngTB.Pur__Return + "' then N'" + LngTB.Purchase + "' when RECTYPE=N'" + LngTB.Sales__Ret + "' then N'" + LngTB.Sales + "' else RECTYPE end),(case when PAYTYPE=N'" + LngTB.Pur__Return + "' then N'" + LngTB.Purchase + "' when PAYTYPE=N'" + LngTB.Sales__Ret + "' then N'" + LngTB.Sales + "' else PAYTYPE end)),ACCMAS.ACCNAME)") + ",'') AS ACCOUNT,IIF(" + tableName + ".PAYID<>'0'," + tableName + ".PAYCASH+" + tableName + ".PAYAMT,0) AS Credit,IIF(" + tableName + ".RECID<>'0'," + tableName + ".RECCASH+" + tableName + ".RECAMT,0) AS Debit,CASE WHEN " + tableName + ".RECID<>0 THEN  " + tableName + ".RECTYPE WHEN " + tableName + ".RECID=0 AND " + tableName + ".PAYID<>0 THEN " + tableName + ".PAYTYPE WHEN " + tableName + ".RECID=0 AND " + tableName + ".PAYID=0 THEN '' END AS VRTYPE FROM (" + tableName + " LEFT JOIN ACCMAS ON " + tableName + ".ACCID=ACCMAS.ID) LEFT JOIN GRPLDG ON ACCMAS.MGROUP=GRPLDG.GROUPID WHERE (ADJCD='" + AccId + "' OR ACCID='" + AccId + "') AND (RECCASH<>0 OR PAYCASH<>0 ) ) AS F GROUP BY GRPNAME,ACCOUNT,VRTYPE ORDER BY ACCOUNT,VRTYPE";
            return await db.GetDatatable(qry);
        }

        public async Task CreateTable_CS()
        {
            string t = "'TRUE'";
            string f = "'FALSE'";

            tbPURD = "TMP_PURD" + DateTime.Now.Hour.ToString() + "_" + DateTime.Now.Minute.ToString() + "_" + DateTime.Now.Second.ToString();           

            qry = @"SELECT * INTO " + tbPURD + @" FROM (
SELECT VRTYPE, VRNO, PURDATE, BILLNO, BILLDATE, SUPCODE, ETYPE, CODE, AMOUNT, TAX, BTYPE, LOGCD, TAXAMT, RETURNFLG, ORDNO, SLCODE, VATFLG, CURCONRATE, CURCODE, DFLAG, ORGAMT, ORGTAXAMT, CANCELFLG, ADJCD, GCCCD, VSVRTYPE FROM PURD WHERE ETYPE NOT IN ('T', 'D')

UNION ALL

SELECT PURD.VRTYPE, PURD.VRNO, PURD.PURDATE, PURD.BILLNO, PURD.BILLDATE, PURD.SUPCODE, PURD.ETYPE, PURD.CODE, PURD.AMOUNT, PURD.TAX, PURD.BTYPE, PURD.LOGCD, PURD.TAXAMT, PURD.RETURNFLG, PURD.ORDNO, PURD.SLCODE, PURD.VATFLG, PURD.CURCONRATE, PURD.CURCODE, PURD.DFLAG, PURD.ORGAMT, PURD.ORGTAXAMT, PURD.CANCELFLG, PURD.ADJCD, PURD.GCCCD, PURD.VSVRTYPE FROM PURD INNER JOIN PURM ON PURD.VRNO = PURM.VRNO WHERE PURM.SLFLG = " + f + @" AND PURD.ETYPE IN ('T', 'D')

UNION ALL

SELECT PURD.VRTYPE, PURD.VRNO, PURD.PURDATE, PURD.BILLNO, PURD.BILLDATE, PURD.SUPCODE, PURD.ETYPE, PURD.CODE, ROUND(DTLS.AMOUNT, " + Variables.DecimalPoint + ") AS AMOUNT, PURD.TAX, PURD.BTYPE, PURD.LOGCD, IIF(PURD.TAXAMT <> 0, ROUND(DTLS.TAXAMT, " + Variables.DecimalPoint + @"), PURD.TAXAMT) AS TAXAMT, PURD.RETURNFLG, PURD.ORDNO, DTLS.SLCODE, PURD.VATFLG, PURD.CURCONRATE, PURD.CURCODE, PURD.DFLAG, PURD.ORGAMT, PURD.ORGTAXAMT, PURD.CANCELFLG, PURD.ADJCD, PURD.GCCCD, PURD.VSVRTYPE FROM PURD
INNER JOIN (SELECT PURT.VRNO, PURT.TAXCODE, PURT.SLCODE,
SUM(PURT.QTY*( IIF(PURM.INFORMAT=3, ((PURT.PRRATE/(1+(PURT.TAX/100)))-PURT.DISC-PURT.LDISCAMT), (PURT.PRRATE-PURT.DISC-PURT.LDISCAMT)))) AS AMOUNT,
SUM(PURT.QTY*( IIF(PURM.INFORMAT=3, ((PURT.PRRATE/(1+(PURT.TAX/100)))-PURT.DISC-PURT.LDISCAMT), (PURT.PRRATE-PURT.DISC-PURT.LDISCAMT)))*PURT.TAX/100) AS TAXAMT 
FROM PURT INNER JOIN PURM ON PURT.VRNO = PURM.VRNO WHERE PURM.CANCELFLG = " + f + " AND PURM.SLFLG = " + t + @" GROUP BY PURT.VRNO, PURT.TAXCODE, PURT.SLCODE) DTLS ON DTLS.VRNO = PURD.VRNO 
WHERE DTLS.TAXCODE = PURD.CODE AND PURD.ETYPE = 'T'

UNION ALL

SELECT PURD.VRTYPE, PURD.VRNO, PURD.PURDATE, PURD.BILLNO, PURD.BILLDATE, PURD.SUPCODE, PURD.ETYPE, DTLS.CODE, ROUND(DTLS.AMOUNT, " + Variables.DecimalPoint + @") AS AMOUNT, PURD.TAX, PURD.BTYPE, PURD.LOGCD, PURD.TAXAMT, PURD.RETURNFLG, PURD.ORDNO, DTLS.SLCODE, PURD.VATFLG, PURD.CURCONRATE, PURD.CURCODE, PURD.DFLAG, PURD.ORGAMT, PURD.ORGTAXAMT, PURD.CANCELFLG, PURD.ADJCD, PURD.GCCCD, PURD.VSVRTYPE 
FROM (SELECT DISTINCT VRTYPE, VRNO, PURDATE, BILLNO, BILLDATE, SUPCODE, ETYPE, TAX, BTYPE, LOGCD, TAXAMT, RETURNFLG, ORDNO, VATFLG, CURCONRATE, CURCODE, DFLAG, ORGAMT, ORGTAXAMT, CANCELFLG, ADJCD, GCCCD, VSVRTYPE FROM PURD WHERE ETYPE = 'D') PURD
INNER JOIN (SELECT PURT.VRNO, PURT.TAXCODE, PURT.SLCODE,
SUM(PURT.QTY*( IIF(PURM.INFORMAT=3, ((PURT.PRRATE/(1+(PURT.TAX/100)))-PURT.DISC-PURT.LDISCAMT), (PURT.PRRATE-PURT.DISC-PURT.LDISCAMT)))) AS AMOUNT,
SUM(PURT.QTY*( IIF(PURM.INFORMAT=3, ((PURT.PRRATE/(1+(PURT.TAX/100)))-PURT.DISC-PURT.LDISCAMT), (PURT.PRRATE-PURT.DISC-PURT.LDISCAMT)))*PURT.TAX/100) AS TAXAMT,
IIF(PURM.TAGACC = " + t + " AND PURM.SLPRACC <> 0, PURM.SLPRACC ,IIF(1 = " + (Variables.TagAccMstr ? "1" : "0") + " AND PRMAST.PURACCODE IS NOT NULL AND PRMAST.PURACCODE <> 0, PRMAST.PURACCODE, IIF(PRGRPMAS.TAGACCFLG IS NOT NULL AND PRGRPMAS.TAGACCFLG = " + t + @" AND PRGRPMAS.PURACCID IS NOT NULL AND PRGRPMAS.PURACCID <> 0, PRGRPMAS.PURACCID, 8))) AS CODE
FROM (((PURT INNER JOIN (SELECT PURM.VRNO, PURM.INFORMAT, IIF(VRSYSTEM.TAGACC IS NULL, PURM.CANCELFLG, VRSYSTEM.TAGACC) AS TAGACC, IIF(VRSYSTEM.SLPRACC IS NULL, 0, VRSYSTEM.SLPRACC) AS SLPRACC FROM PURM LEFT JOIN VRSYSTEM ON PURM.VSVRTYPE = VRSYSTEM.ID WHERE PURM.CANCELFLG = " + f + " AND PURM.SLFLG = " + t + @") PURM ON PURT.VRNO = PURM.VRNO) LEFT JOIN PRMAST ON PURT.PRCODE = PRMAST.PRCODE) LEFT JOIN PRGRPMAS ON PRMAST.GROUPCODE = PRGRPMAS.PRGRPID)
GROUP BY PURT.VRNO, PURT.TAXCODE, PURT.SLCODE, PURM.TAGACC, PURM.SLPRACC, PRMAST.PURACCODE, PRGRPMAS.TAGACCFLG, PRGRPMAS.PURACCID) DTLS ON DTLS.VRNO = PURD.VRNO
) FINAL ORDER BY VRNO";

            int R = await db.Execute(qry);

            //

            tbSALD = "TMP_SALD" + DateTime.Now.Hour.ToString() + "_" + DateTime.Now.Minute.ToString() + "_" + DateTime.Now.Second.ToString();            

            qry = @"SELECT * INTO " + tbSALD + @" FROM (
SELECT VRTYPE, VRNO, INVDATE, CUSCODE, ETYPE, CODE, AMOUNT, TAX, BTYPE, LOGCD, TAXAMT, RETURNFLG, SLCODE, VATFLG, CURCONRATE, CURCODE, ORDNO, DFLAG, ORGAMT, ORGTAXAMT, CANCELFLG, BLCODE, ADJCD, VSVRTYPE FROM SALD WHERE ETYPE NOT IN ('T', 'D')

UNION ALL

SELECT VRTYPE, SALD.VRNO, SALD.INVDATE, SALD.CUSCODE, SALD.ETYPE, SALD.CODE, SALD.AMOUNT, SALD.TAX, SALD.BTYPE, SALD.LOGCD, SALD.TAXAMT, SALD.RETURNFLG, SALD.SLCODE, SALD.VATFLG, SALD.CURCONRATE, SALD.CURCODE, SALD.ORDNO, SALD.DFLAG, SALD.ORGAMT, SALD.ORGTAXAMT, SALD.CANCELFLG, SALD.BLCODE, SALD.ADJCD, SALD.VSVRTYPE FROM SALD INNER JOIN SALM ON SALD.VRNO = SALM.INVNO WHERE SALM.SLFLG = " + f + @" AND SALD.ETYPE IN ('T', 'D')

UNION ALL

SELECT SALD.VRTYPE, SALD.VRNO, SALD.INVDATE, SALD.CUSCODE, SALD.ETYPE, SALD.CODE, ROUND(DTLS.AMOUNT, " + Variables.DecimalPoint + ") AS AMOUNT, SALD.TAX, SALD.BTYPE, SALD.LOGCD, IIF(SALD.TAXAMT <> 0, ROUND(DTLS.TAXAMT, " + Variables.DecimalPoint + @"), SALD.TAXAMT) AS TAXAMT, SALD.RETURNFLG, DTLS.SLCODE, SALD.VATFLG, SALD.CURCONRATE, SALD.CURCODE, SALD.ORDNO, SALD.DFLAG, SALD.ORGAMT, SALD.ORGTAXAMT, SALD.CANCELFLG, SALD.BLCODE, SALD.ADJCD, SALD.VSVRTYPE FROM SALD
INNER JOIN (SELECT SALT.INVNO, SALT.TAXCODE, SALT.SLCODE,
SUM(SALT.QTY*(IIF(SALM.INFORMAT=3, ((SALT.RATE-SALT.TOTDISC)/(1+SALT.TAX/100)), SALT.RATE-SALT.TOTDISC))) AS AMOUNT,
SUM(SALT.QTY*(IIF(SALM.INFORMAT=3, ((SALT.RATE-SALT.TOTDISC)/(1+SALT.TAX/100)), SALT.RATE-SALT.TOTDISC))*SALT.TAX/100) AS TAXAMT
FROM SALT INNER JOIN SALM ON SALT.INVNO = SALM.INVNO WHERE SALM.CANCELFLG = " + f + " AND SALM.SLFLG = " + t + @" GROUP BY SALT.INVNO, SALT.TAXCODE, SALT.SLCODE) DTLS ON DTLS.INVNO = SALD.VRNO
WHERE DTLS.TAXCODE = SALD.CODE AND SALD.ETYPE = 'T'

UNION ALL

SELECT SALD.VRTYPE, SALD.VRNO, SALD.INVDATE, SALD.CUSCODE, SALD.ETYPE, DTLS.CODE, ROUND(DTLS.AMOUNT, " + Variables.DecimalPoint + @") AS AMOUNT, SALD.TAX, SALD.BTYPE, SALD.LOGCD, SALD.TAXAMT, SALD.RETURNFLG, DTLS.SLCODE, SALD.VATFLG, SALD.CURCONRATE, SALD.CURCODE, SALD.ORDNO, SALD.DFLAG, SALD.ORGAMT, SALD.ORGTAXAMT, SALD.CANCELFLG, SALD.BLCODE, SALD.ADJCD, SALD.VSVRTYPE 
FROM (SELECT DISTINCT VRTYPE, VRNO, INVDATE, CUSCODE, ETYPE, TAX, BTYPE, LOGCD, TAXAMT, RETURNFLG, VATFLG, CURCONRATE, CURCODE, ORDNO, DFLAG, ORGAMT, ORGTAXAMT, CANCELFLG, BLCODE, ADJCD, VSVRTYPE FROM SALD WHERE ETYPE = 'D') SALD
INNER JOIN (SELECT SALT.INVNO, SALT.TAXCODE, SALT.SLCODE,
SUM(SALT.QTY*(IIF(SALM.INFORMAT=3, ((SALT.RATE-SALT.TOTDISC)/(1+SALT.TAX/100)), SALT.RATE-SALT.TOTDISC))) AS AMOUNT,
SUM(SALT.QTY*(IIF(SALM.INFORMAT=3, ((SALT.RATE-SALT.TOTDISC)/(1+SALT.TAX/100)), SALT.RATE-SALT.TOTDISC))*SALT.TAX/100) AS TAXAMT,
IIF(SALM.TAGACC = " + t + " AND SALM.SLPRACC <> 0, SALM.SLPRACC ,IIF(1 = " + (Variables.TagAccMstr ? "1" : "0") + " AND PRMAST.PURACCODE IS NOT NULL AND PRMAST.PURACCODE <> 0, PRMAST.PURACCODE, IIF(PRGRPMAS.TAGACCFLG IS NOT NULL AND PRGRPMAS.TAGACCFLG = " + t + @" AND PRGRPMAS.PURACCID IS NOT NULL AND PRGRPMAS.PURACCID <> 0, PRGRPMAS.PURACCID, 7))) AS CODE
FROM (((SALT INNER JOIN (SELECT SALM.INVNO, SALM.INFORMAT, IIF(VRSYSTEM.TAGACC IS NULL, SALM.CANCELFLG, VRSYSTEM.TAGACC) AS TAGACC, IIF(VRSYSTEM.SLPRACC IS NULL, 0, VRSYSTEM.SLPRACC) AS SLPRACC FROM SALM LEFT JOIN VRSYSTEM ON SALM.VSVRTYPE = VRSYSTEM.ID WHERE SALM.CANCELFLG = " + f + " AND SALM.SLFLG = " + t + @" ) SALM ON SALT.INVNO = SALM.INVNO) LEFT JOIN PRMAST ON SALT.PRCODE = PRMAST.PRCODE) LEFT JOIN PRGRPMAS ON PRMAST.GROUPCODE = PRGRPMAS.PRGRPID)
GROUP BY SALT.INVNO, SALT.TAXCODE, SALT.SLCODE, SALM.TAGACC, SALM.SLPRACC, PRMAST.PURACCODE, PRGRPMAS.TAGACCFLG, PRGRPMAS.PURACCID) DTLS ON DTLS.INVNO = SALD.VRNO
) FINAL ORDER BY VRNO";

            R = await db.Execute(qry);
        }

