                     @" SELECT COSTCMAS.CODE AS ACCID,COSTCMAS.COSTCNAME AS ACCNAME, COSTCMAS.OPNBAL AS OPENBAL, 0 AS DEBIT, 0 AS CREDIT,'' as Type FROM " + Functions.VRSYS_ALLOWBR_COSTCMAS() + "COSTCMAS " + Functions.VRSYS_ALLOWBR_REPORT(false, "COSTCMAS", true) +
