                qry = " SELECT DISTINCT ACCID AS AccId,ACCNAME AS AccName,0 AS OpenBal, IIF(SUM(DEBIT)=0,NULL,FORMAT(SUM(DEBIT), '" + Variables.DecString + "')) AS Debit,IIF(SUM(CREDIT)=0,NULL,FORMAT(SUM(CREDIT), '" + Variables.DecString + "')) AS Credit,FORMAT(SUM(CREDIT) -SUM(DEBIT),'" + Variables.DecString + "') AS Balance,'' as Type FROM(" +
                      @" SELECT COSTCMAS.CODE AS ACCID,COSTCMAS.COSTCNAME AS ACCNAME, 0 AS OPENBAL, 0 AS DEBIT, 0 AS CREDIT,'' as Type FROM COSTCMAS " + Functions.VRSYS_ALLOWBR_REPORT(false, "COSTCMAS", true) +
                      @" UNION ALL SELECT        " + tableName + ".SLCODE AS ACCID,COSTCMAS.COSTCNAME AS ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".PAYCASH) + SUM(" + tableName + ".PAYAMT) AS DEBIT, SUM(" + tableName + ".RECCASH) + SUM(" + tableName + ".RECAMT) AS CREDIT,'' as Type FROM(" + Functions.VRSYS_ALLOWBR_COSTCMAS() + "COSTCMAS INNER JOIN " + tableName + " ON COSTCMAS.CODE = " + tableName + ".SLCODE)" + " WHERE " + tableName + ".ACCID <> " + Variables.CashCD + Functions.VRSYS_ALLOWBR_REPORT(true, "COSTCMAS", true) + " GROUP BY " + tableName + ".SLCODE, COSTCMAS.COSTCNAME) AS T GROUP BY ACCID,ACCNAME " +
                      @" UNION ALL SELECT DISTINCT 0 AS AccId,N'" + LngTB.Total + "' AS AccName,0 AS OpenBal, FORMAT(SUM(DEBIT),'" + Variables.DecString + "') AS Debit,FORMAT(SUM(CREDIT),'" + Variables.DecString + "') AS Credit,FORMAT(SUM(CREDIT) -SUM(DEBIT),'" + Variables.DecString + "') AS Balance,'B' as Type FROM(SELECT COSTCMAS.CODE AS ACCID,COSTCMAS.COSTCNAME AS ACCNAME, 0 AS OPENBAL, 0 AS DEBIT , 0 AS CREDIT,'B' as Type FROM " + Functions.VRSYS_ALLOWBR_COSTCMAS() + "COSTCMAS " + Functions.VRSYS_ALLOWBR_REPORT(false, "COSTCMAS", true) +
                      @" UNION ALL SELECT        " + tableName + ".SLCODE AS ACCID, COSTCMAS.COSTCNAME AS ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".PAYCASH) + SUM(" + tableName + ".PAYAMT) AS DEBIT, SUM(" + tableName + ".RECCASH) + SUM(" + tableName + ".RECAMT) AS CREDIT,'' as Type FROM(" + Functions.VRSYS_ALLOWBR_COSTCMAS() + "COSTCMAS INNER JOIN " + tableName + " ON COSTCMAS.CODE = " + tableName + ".SLCODE)" + " WHERE " + tableName + ".ACCID <> " + Variables.CashCD + Functions.VRSYS_ALLOWBR_REPORT(true, "COSTCMAS", true) + " GROUP BY " + tableName + ".SLCODE, COSTCMAS.COSTCNAME) AS T ";
            }
            return await db.GetDatatable(qry);
        }

