                     @" UNION ALL SELECT 0 AS OrderCode,COSTCMAS.COSTCNAME AS OrdName,0 AS LedgerID,'' AS LedgerName," + OpTable + ".SLCODE AS ACCID, COSTCMAS.COSTCNAME AS ACCNAME, SUM(" + OpTable + ".RECCASH) + SUM(" + OpTable + ".RECAMT) - SUM(" + OpTable + ".PAYCASH) - SUM(" + OpTable + ".PAYAMT) AS OPENBAL, 0 AS DEBIT, 0 AS CREDIT,'' as Type FROM(" + OpTable + " INNER JOIN COSTCMAS ON " + OpTable + ".SLCODE = COSTCMAS.CODE)" + " WHERE " + OpTable + ".ACCID <> " + Variables.CashCD + Functions.VRSYS_ALLOWBR_REPORT(true, "COSTCMAS", true) + "  GROUP BY " + OpTable + ".SLCODE, COSTCMAS.COSTCNAME" +
