        public async Task<DataTable> TrialBalance(bool open, bool Detailed, bool Unapproved = true)
        {
            if (open == true)
            {
                if (Detailed == true)
                {
                    //DETAILED WITH OPENING BALANCE SQL-Alphabetic
                    qry = " SELECT AccId, AccName,Format(OpenBal,'" + Variables.DecString + "') AS OpenBal,IIF( OpenBal>0, Format(OpenBal,'" + Variables.DecString + "'),NULL) AS OpCredit,IIF( OpenBal<0, Format(-1*OpenBal,'" + Variables.DecString + "'),NULL) AS OpDebit,Format(Debit,'" + Variables.DecString + "') AS  Debit,Format(Credit,'" + Variables.DecString + "') AS Credit,Format(Balance,'" + Variables.DecString + "') AS  Balance,0 AS GroupId, 0 As OrderNo,'' As Type,Format( IIF(Balance IS NOT NULL AND CAST(Balance AS DECIMAL(18," + Variables.DecimalPoint + "))>=0,CAST(Balance AS DECIMAL(18," + Variables.DecimalPoint + ")),0),'" + Variables.DecString + "') AS CCredit,Format( IIF(Balance IS NOT NULL AND CAST(Balance AS DECIMAL(18," + Variables.DecimalPoint + "))<0,-1*CAST(Balance AS DECIMAL(18," + Variables.DecimalPoint + ")),0),'" + Variables.DecString + "') AS CDebit FROM( SELECT DISTINCT ACCID AS AccId,ACCNAME AS AccName,SUM(OPENBAL) AS OpenBal,SUM(DEBIT) AS Debit,SUM(CREDIT) AS Credit,SUM(OPENBAL) +SUM(CREDIT) -SUM(DEBIT) AS Balance FROM(SELECT ID AS ACCID, ACCNAME, OPENBAL, 0 AS DEBIT, 0 AS CREDIT FROM " + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS WHERE(ID = '" + Variables.CashCD + "')" +
                          @" UNION ALL SELECT ACCMAS_2.ID AS ACCID, ACCMAS_2.ACCNAME AS ACCNAME,SUM(" + OpTable + ".PAYCASH)-SUM(" + OpTable + ".RECCASH) AS OPENBAL, 0 AS DEBIT, 0 AS CREDIT FROM ACCMAS ACCMAS_2 INNER JOIN " + OpTable + " ON ACCMAS_2.ID=" + OpTable + ".ADJCD WHERE (ACCMAS_2.ID = '" + Variables.CashCD + "') AND (CAST(" + OpTable + ".RECCASH AS DECIMAL(18," + Variables.DecimalPoint + ")) <> 0) OR (ACCMAS_2.ID = " + Variables.CashCD + ") AND (CAST(" + OpTable + ".PAYCASH AS DECIMAL(18," + Variables.DecimalPoint + ")) <> 0) GROUP BY ACCMAS_2.ID , ACCMAS_2.ACCNAME " +
                          @" UNION ALL SELECT ACCMAS_1.ID AS ACCID, ACCMAS_1.ACCNAME AS ACCNAME, 0 AS OPENBAL," + tableName + ".RECCASH  AS DEBIT,   " + tableName + ".PAYCASH AS CREDIT FROM ACCMAS ACCMAS_1 INNER JOIN " + tableName + " ON ACCMAS_1.ID=" + tableName + ".ADJCD WHERE  (ACCMAS_1.ID = '" + Variables.CashCD + "') AND (CAST(" + tableName + ".RECCASH AS DECIMAL(18," + Variables.DecimalPoint + ")) <> 0) OR (ACCMAS_1.ID = '" + Variables.CashCD + "') AND (CAST(" + tableName + ".PAYCASH AS DECIMAL(18," + Variables.DecimalPoint + ")) <> 0)) CT GROUP BY ACCID, ACCNAME " +

                        @" UNION ALL SELECT DISTINCT ACCID AS AccId,ACCNAME AS AccName,SUM(OPENBAL) AS OpenBal, SUM(DEBIT) AS Debit,SUM(CREDIT) AS Credit,SUM(OPENBAL) +SUM(CREDIT) -SUM(DEBIT) AS Balance FROM(" +
                        @" SELECT ID AS ACCID, ACCNAME, OPENBAL, 0 AS DEBIT, 0 AS CREDIT FROM " + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS WHERE ACCMAS.ID<>'" + Variables.CashCD + "'" + Functions.APRVLR(true, Unapproved, "ACCMAS") + Functions.VRSYS_ALLOWBR_REPORT(true, "ACCMAS", true) +
                          @" UNION ALL SELECT " + OpTable + ".ACCID, ACCMAS.ACCNAME, SUM(" + OpTable + ".RECCASH) + SUM(" + OpTable + ".RECAMT) - SUM(" + OpTable + ".PAYCASH) - SUM(" + OpTable + ".PAYAMT) AS OPENBAL, 0 AS DEBIT, 0 AS CREDIT FROM(" + OpTable + " INNER JOIN ACCMAS ON " + OpTable + ".ACCID = ACCMAS.ID) WHERE ACCMAS.ID<>'" + Variables.CashCD + "' GROUP BY " + OpTable + ".ACCID, ACCMAS.ACCNAME" +
