                        @" UNION ALL SELECT DISTINCT ACCID AS AccId,ACCNAME AS AccName,CAST(SUM(OPENBAL) AS DECIMAL(18," + Variables.DecimalPoint + ")) AS OpenBal, CAST(SUM(DEBIT) AS DECIMAL(18," + Variables.DecimalPoint + ")) AS Debit,CAST(SUM(CREDIT) AS DECIMAL(18," + Variables.DecimalPoint + ")) AS Credit,CAST(SUM(OPENBAL) +SUM(CREDIT) -SUM(DEBIT) AS DECIMAL(18," + Variables.DecimalPoint + ")) AS Balance FROM(" +
                        @" SELECT ID AS ACCID, ACCNAME, OPENBAL, 0 AS DEBIT, 0 AS CREDIT FROM " + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS WHERE ACCMAS.ID<>'" + Variables.CashCD + "'" + Functions.APRVLR(true, Unapproved, "ACCMAS") + Functions.VRSYS_ALLOWBR_REPORT(true, "ACCMAS", true) +
