        public async Task<DataTable> TrialBalanceSummary(int GrpID, string GrpName, string SubGrpIDS)
        {
            qry = @"SELECT  0 AS AccId, '" + GrpName + "' AS AccName, Format(SUM(" + tb_name + ".OpenBal),'" + Variables.DecString + @"') AS OpenBal
                    ,IIF(SUM(" + tb_name + ".OpenBal)>0, Format(SUM(" + tb_name + ".OpenBal),'" + Variables.DecString + @"'),null) AS OpCredit
                    ,IIF(SUM(" + tb_name + ".OpenBal)<0, Format(-1*SUM(" + tb_name + ".OpenBal),'" + Variables.DecString + @"'),null) AS OpDebit 
                    , Format(SUM(" + tb_name + ".Debit),'" + Variables.DecString + "') AS Debit, Format(SUM(" + tb_name + ".Credit),'" + Variables.DecString + @"') AS Credit
                    , Format(SUM(" + tb_name + ".Balance),'" + Variables.DecString + "') AS Balance, " + GrpID + @" AS GroupId, 0 As OrderNo,'B'as Type 
                    FROM ACCMAS INNER JOIN  " + tb_name + " ON ACCMAS.ID = " + tb_name + @".AccId WHERE ACCMAS.MGROUP IN(" + SubGrpIDS + ")";

            return await db.GetDatatable(qry);
        }

        public async Task<DataTable> CashTotal()
        {
            qry = @"  SELECT DISTINCT 0 AS AccId,N'" + LngTB.Total + "' AS AccName,FORMAT(SUM(OPENBAL),'" + Variables.DecString + "') AS OpenBal, FORMAT(SUM(DEBIT),'" + Variables.DecString + "') AS Debit,FORMAT(SUM(CREDIT),'" + Variables.DecString + "') AS Credit,FORMAT(SUM(OPENBAL) +SUM(CREDIT) -SUM(DEBIT),'" + Variables.DecString + "') AS Balance,'B' As Type FROM(SELECT        ID AS ACCID, ACCNAME, OPENBAL, 0 AS DEBIT , 0 AS CREDIT FROM " + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS WHERE ACCMAS.ID='" + Variables.CashCD + "'" +
                   @" UNION ALL SELECT " + OpTable + ".ACCID, ACCMAS.ACCNAME, SUM(" + OpTable + ".PAYCASH)  - SUM(" + OpTable + ".RECCASH)  AS OPENBAL, 0 AS DEBIT, 0 AS CREDIT FROM(" + OpTable + " INNER JOIN ACCMAS ON " + OpTable + ".ACCID = ACCMAS.ID) WHERE " + OpTable + ".ADACC='" + Variables.CashCD + "'  GROUP BY " + OpTable + ".ACCID, ACCMAS.ACCNAME" +
                    @" UNION ALL SELECT        " + tableName + ".ACCID, ACCMAS.ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".RECCASH)  AS DEBIT, SUM(" + tableName + ".PAYCASH)  AS CREDIT FROM(ACCMAS INNER JOIN " + tableName + " ON ACCMAS.ID = " + tableName + ".ACCID) WHERE " + tableName + ".ADACC='" + Variables.CashCD + "'  GROUP BY " + tableName + ".ACCID, ACCMAS.ACCNAME) AS T ";
            return await db.GetDatatable(qry);
        }

