        public async Task<DataTable> PRV_LedgerBalance(bool Unapproved)
        {
            qry = "SELECT ACCMAS.ID, ACCMAS.ACCODE, ACCMAS.ACCNAME, ACCMAS.OPENBAL, PRVDT.BALANCE FROM ((" + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS INNER JOIN GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID) LEFT JOIN (SELECT " + Variables.CashCD + " AS ACCID, SUM(PAYCASH) - SUM(RECCASH) AS BALANCE FROM " + tableName + " WHERE ACCID = " + Variables.CashCD + " OR ADJCD = " + Variables.CashCD + ") PRVDT ON PRVDT.ACCID = ACCMAS.ID) WHERE GRPLDG.FORDER = 'B' AND ACCMAS.ID = " + Variables.CashCD + Functions.APRVLR(true, Unapproved, "ACCMAS") + @"
            UNION ALL
            SELECT ACCMAS.ID, ACCMAS.ACCODE, ACCMAS.ACCNAME, ACCMAS.OPENBAL, PRVDT.BALANCE FROM ((" + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS INNER JOIN GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID) LEFT JOIN (SELECT ACCID, SUM(RECCASH+RECAMT) - SUM(PAYCASH+PAYAMT) AS BALANCE FROM " + tableName + " GROUP BY ACCID) PRVDT ON PRVDT.ACCID = ACCMAS.ID) WHERE GRPLDG.FORDER = 'B' AND ACCMAS.ID <> " + Variables.CashCD + Functions.APRVLR(true, Unapproved, "ACCMAS");
            return await db.GetDatatable(qry);
        }

