        public async Task<Decimal> NetProfit(string FOrder, bool Unapproved = true)
        {
            string ret = "";
            if (FOrder == "B")
            {
                qry = @"SELECT SUM(Balance) FROM(SELECT DISTINCT ACCID AS AccId,ACCNAME AS AccName,CAST(SUM(OPENBAL) +SUM(CREDIT) -SUM(DEBIT) AS DECIMAL(18," + Variables.DecimalPoint + ")) AS Balance FROM(SELECT   GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(ACCMAS.OPENBAL) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT FROM (" + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS  INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID) WHERE (GRPLDG.FORDER = 'M')" + Functions.APRVLR(true, Unapproved, "ACCMAS") + Functions.VRSYS_ALLOWBR_REPORT(true, "ACCMAS", true) + "  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME " +
                    " UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(" + OpTable + ".RECCASH) + SUM(" + OpTable + ".RECAMT) - SUM(" + OpTable + ".PAYCASH) - SUM(" + OpTable + ".PAYAMT) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT FROM ((ACCMAS INNER JOIN  " + OpTable + " ON ACCMAS.ID = " + OpTable + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = 'M') GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME " +
                    " UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".RECCASH) + SUM(" + tableName + ".RECAMT) AS CREDIT, SUM(" + tableName + ".PAYCASH) + SUM(" + tableName + ".PAYAMT) AS DEBIT FROM ((ACCMAS INNER JOIN  " + tableName + " ON ACCMAS.ID = " + tableName + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = 'M')  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME) AS T GROUP BY ACCID,ACCNAME)TT";
            }
            else
            {
                qry = @"SELECT SUM(Balance) FROM(SELECT DISTINCT ACCID AS AccId,ACCNAME AS AccName,CAST(SUM(CREDIT) -SUM(DEBIT) AS DECIMAL(18," + Variables.DecimalPoint + ")) AS Balance FROM(SELECT   GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(ACCMAS.OPENBAL) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT FROM (" + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS  INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID) WHERE (GRPLDG.FORDER = '" + FOrder + "')" + Functions.APRVLR(true, Unapproved, "ACCMAS") + Functions.VRSYS_ALLOWBR_REPORT(true, "ACCMAS", true) + "  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME " +
                    " UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(" + OpTable + ".RECCASH) + SUM(" + OpTable + ".RECAMT) - SUM(" + OpTable + ".PAYCASH) - SUM(" + OpTable + ".PAYAMT) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT FROM ((ACCMAS INNER JOIN  " + OpTable + " ON ACCMAS.ID = " + OpTable + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = '" + FOrder + "') GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME " +
                    " UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".RECCASH) + SUM(" + tableName + ".RECAMT) AS CREDIT, SUM(" + tableName + ".PAYCASH) + SUM(" + tableName + ".PAYAMT) AS DEBIT FROM ((ACCMAS INNER JOIN  " + tableName + " ON ACCMAS.ID = " + tableName + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = '" + FOrder + "')  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME) AS T GROUP BY ACCID,ACCNAME)TT";

            }
            ret = await db.ReturnStringValue(qry);
            while (ret == "Error")
                ret = await db.ReturnStringValue(qry); ;

            if (ret != "" && ret != "Error")
                return Convert.ToDecimal(ret);
            else
                return 0;
        }

