            if (FOrder == "B")
            {
                qry = @"SELECT  ACCID AS AccId,ACCNAME AS AccName,FORMAT(SUM(OPENBAL) -SUM(CREDIT) +SUM(DEBIT),'" + Variables.DecString + "') AS Balance,SEQNO FROM(SELECT   GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(-1*ACCMAS.OPENBAL) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT,GRPLDG.SEQNO AS SEQNO FROM (" + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS  INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID) WHERE (GRPLDG.FORDER = '" + FOrder + "')" + Functions.APRVLR(true, Unapproved, "ACCMAS") + Functions.VRSYS_ALLOWBR_REPORT(true, "ACCMAS", true) + "  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME,GRPLDG.SEQNO" +
                @" UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(" + OpTable + ".PAYCASH) + SUM(" + OpTable + ".PAYAMT)-SUM(" + OpTable + ".RECCASH) - SUM(" + OpTable + ".RECAMT) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT,GRPLDG.SEQNO AS SEQNO FROM ((ACCMAS INNER JOIN  " + OpTable + " ON ACCMAS.ID = " + OpTable + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = '" + FOrder + "') GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME,GRPLDG.SEQNO" +
                @" UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".RECCASH) + SUM(" + tableName + ".RECAMT) AS CREDIT, SUM(" + tableName + ".PAYCASH) + SUM(" + tableName + ".PAYAMT) AS DEBIT,GRPLDG.SEQNO AS SEQNO FROM ((ACCMAS INNER JOIN  " + tableName + " ON ACCMAS.ID = " + tableName + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = '" + FOrder + "')  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME,GRPLDG.SEQNO) AS T GROUP BY ACCID,ACCNAME,SEQNO ORDER BY SEQNO";
                return await db.GetDatatable(qry);
            }
            else
            {
                qry = @"SELECT DISTINCT  ACCID AS AccId,ACCNAME AS AccName,CAST(SUM(CREDIT) -SUM(DEBIT) AS DECIMAL(18," + Variables.DecimalPoint + ")) AS Balance FROM(SELECT   GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(ACCMAS.OPENBAL) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT FROM (" + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS  INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID) WHERE (GRPLDG.FORDER = '" + FOrder + "')" + Functions.APRVLR(true, Unapproved, "ACCMAS") + Functions.VRSYS_ALLOWBR_REPORT(true, "ACCMAS", true) + "  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME" +
                @" UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, SUM(" + OpTable + ".RECCASH) + SUM(" + OpTable + ".RECAMT) - SUM(" + OpTable + ".PAYCASH) - SUM(" + OpTable + ".PAYAMT) AS OPENBAL, 0 AS CREDIT, 0 AS DEBIT FROM ((ACCMAS INNER JOIN  " + OpTable + " ON ACCMAS.ID = " + OpTable + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = '" + FOrder + "') GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME" +
                @" UNION ALL SELECT  GRPLDG.GROUPID AS ACCID, GRPLDG.GROUPNAME AS ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".RECCASH) + SUM(" + tableName + ".RECAMT) AS CREDIT, SUM(" + tableName + ".PAYCASH) + SUM(" + tableName + ".PAYAMT) AS DEBIT FROM ((ACCMAS INNER JOIN  " + tableName + " ON ACCMAS.ID = " + tableName + ".ACCID) INNER JOIN  GRPLDG ON ACCMAS.MGROUP = GRPLDG.GROUPID)  WHERE (GRPLDG.FORDER = '" + FOrder + "')  GROUP BY GRPLDG.GROUPID, GRPLDG.GROUPNAME) AS T GROUP BY ACCID,ACCNAME";
                return await db.GetDatatable(qry);
            }
        }

        public async Task<decimal> CashBalance()
        {
            qry = "SELECT SUM(" + OpTable + ".RECCASH)-SUM(" + OpTable + ".PAYCASH) AS BALANCE FROM " + OpTable + "";
            decimal BAL = await db.ReturnDecValue(qry);
            qry = "SELECT SUM(" + tableName + ".RECCASH)-SUM(" + tableName + ".PAYCASH) AS BALANCE FROM " + tableName + " ";
            BAL += await db.ReturnDecValue(qry);
            return BAL;
        }

        public async Task<decimal> LedgerCurBalance(int AccId)
        {
            qry = "SELECT SUM(" + tableName + ".RECCASH+" + tableName + ".RECAMT)-SUM(" + tableName + ".PAYCASH+" + tableName + ".PAYAMT) AS BALANCE FROM " + tableName + " WHERE " + tableName + ".ACCID='" + AccId + "'";
            return await db.ReturnDecValue(qry);
        }

        public async Task<DataTable> CashTotalNew()
        {
            qry = @"  SELECT DISTINCT 0 AS AccId,'Total' AS AccName,FORMAT(SUM(OPENBAL),'" + Variables.DecString + "') AS OpenBal, FORMAT(SUM(DEBIT),'" + Variables.DecString + "') AS Debit,FORMAT(SUM(CREDIT),'" + Variables.DecString + "') AS Credit,FORMAT(SUM(OPENBAL) +SUM(CREDIT) -SUM(DEBIT),'" + Variables.DecString + "') AS Balance,'B' As Type FROM(SELECT        ID AS ACCID, ACCNAME, 0 as OPENBAL, IIF(ACCMAS.OPENBAL<0,-1*ACCMAS.OPENBAL,0) AS DEBIT , IIF(ACCMAS.OPENBAL>0,ACCMAS.OPENBAL,0) AS CREDIT FROM " + Functions.VRSYS_ALLOWBR_ACCMAST() + "ACCMAS WHERE ACCMAS.ID='" + Variables.CashCD + "'" +
            @" UNION ALL SELECT " + OpTable + ".ACCID, ACCMAS.ACCNAME, SUM(" + OpTable + ".PAYCASH)  - SUM(" + OpTable + ".RECCASH)  AS OPENBAL, 0 AS DEBIT, 0 AS CREDIT FROM(" + OpTable + " INNER JOIN ACCMAS ON " + OpTable + ".ACCID = ACCMAS.ID) WHERE " + OpTable + ".ADACC='" + Variables.CashCD + "'  GROUP BY " + OpTable + ".ACCID, ACCMAS.ACCNAME" +
            @" UNION ALL SELECT        " + tableName + ".ACCID, ACCMAS.ACCNAME, 0 AS OPENBAL, SUM(" + tableName + ".RECCASH)  AS DEBIT, SUM(" + tableName + ".PAYCASH)  AS CREDIT FROM(ACCMAS INNER JOIN " + tableName + " ON ACCMAS.ID = " + tableName + ".ACCID) WHERE " + tableName + ".ADACC='" + Variables.CashCD + "'  GROUP BY " + tableName + ".ACCID, ACCMAS.ACCNAME) AS T ";
            return await db.GetDatatable(qry);
        }
    }
}
